using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SolutionOne_BusinessLogicLayer.Services.Approval.Interface;
using SolutionOne_BusinessLogicLayer.Services.Common.Interface;
using SolutionOne_Core.ApprovalModels;

namespace SolutionOneWebPortal_API.Controllers.Approval
{
    [Authorize]
    [Route("api/[controller]")]
    [ApiController]
    public class ApprovalController : ControllerBase
    {
        private readonly IApprovalService _service;
        private readonly IRequestMetadata _requestMetadata;

        public ApprovalController(IApprovalService service, IRequestMetadata requestMetadata)
        {
            _service = service;
            _requestMetadata = requestMetadata;
        }

        [HttpPost("CreateInstance")]
        public async Task<IActionResult> CreateInstance([FromBody] CreateApprovalInstanceModel model)
        {
            var result = await _service.CreateInstance(model);
            return StatusCode((int)result.Status, result);
        }

        [HttpPost("Action")]
        public async Task<IActionResult> Action([FromBody] ApprovalActionModel model)
        {
            // EmployeeId always comes from the authenticated session, never the request body - a
            // client-supplied EmployeeId would let any authenticated caller "approve" on someone
            // else's behalf as long as that other employee happens to be a pending approver. The
            // repository's own pending-step lookup is still the real authorization boundary (spec
            // §8); this just makes sure the identity it checks is the caller's, not a claimed one.
            model.EmployeeId = _requestMetadata.EmployeeMasterId;

            var result = await _service.Action(model);
            return StatusCode((int)result.Status, result);
        }

        [HttpGet("GetPending")]
        public async Task<IActionResult> GetPending([FromQuery] long formDocId)
        {
            var result = await _service.GetPending(formDocId, _requestMetadata.EmployeeMasterId);
            return StatusCode((int)result.Status, result);
        }

        [HttpGet("GetTeamRequests")]
        public async Task<IActionResult> GetTeamRequests([FromQuery] long formDocId)
        {
            var result = await _service.GetTeamRequests(formDocId, _requestMetadata.EmployeeMasterId);
            return StatusCode((int)result.Status, result);
        }

        // selectorIds is a comma-separated list for the multi-select (selectorIds=7,9,12); a lone
        // selectorId is also accepted, as in the spec's single-group example. Admin check (403) lives
        // in the service.
        [HttpGet("ResolveSelector")]
        public async Task<IActionResult> ResolveSelector([FromQuery] string? selectorType, [FromQuery] string? selectorIds, [FromQuery] long? selectorId)
        {
            var ids = new List<long>();
            if (selectorId.HasValue)
                ids.Add(selectorId.Value);

            foreach (var part in (selectorIds ?? string.Empty).Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
            {
                if (!long.TryParse(part, out var id))
                    return BadRequest(new { isSuccess = false, status = 400, message = $"'{part}' is not a valid selector id." });
                ids.Add(id);
            }

            var result = await _service.ResolveSelector(selectorType, ids);
            return StatusCode((int)result.Status, result);
        }

        [HttpGet("GetInstanceTimeline/{approvalInstanceId:long}")]
        public async Task<IActionResult> GetInstanceTimeline(long approvalInstanceId)
        {
            var result = await _service.GetInstanceTimeline(approvalInstanceId);
            return StatusCode((int)result.Status, result);
        }
    }
}

