1	import { Component, OnInit } from '@angular/core';
2	import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
3	import { ActivatedRoute, Router } from '@angular/router';
4	import { ApiService } from '../../../../services/api.service';
5	import { ToastService } from '../../../../services/toaster.service';
6	import {
7	  DxButtonModule,
8	  DxCheckBoxModule,
9	  DxNumberBoxModule,
10	  DxSelectBoxModule,
11	  DxTagBoxModule,
12	  DxTemplateModule,
13	} from 'devextreme-angular';
14	import { FormControlPopoutComponent } from '../../../../layout/formcontrol-popout/formcontrol-popout.component';
15	import { AuthService } from '../../../../services/auth.service';
16	import { RbacService } from '../../rbac/services/rbac.service';
17	
18	type ApprovalMode =
19	  | 'default_chain'
20	  | 'any_one'
21	  | 'selected_employee_override'
22	  | 'first_decision_wins';
23	
24	/** Who an approver row actually names. Backend support for all four kinds is live
25	 * (hrmsystembe/Specs/Approval-Admin-Override-And-Group-Selectors-API-Contract.md §3) — a role/
26	 * department/designation row resolves once, when the approval instance is created, to that group's
27	 * then-current active employees with an active login; not re-evaluated against already-pending
28	 * steps. A stage (rows sharing a stageOrder) containing any such row becomes AnyOne instead of
29	 * Unanimous — see stageGroupsPreview. Works for every form doc, Travel Management included. */
30	type SelectorType = 'employee' | 'role' | 'department' | 'designation';
31	
32	interface SelectorRow {
33	  selectorType: SelectorType;
34	  selectorId: number;
35	  designation?: string;
36	  approvalType?: string;
37	  /** Only meaningful for default_chain (Approval-Engine-API-Contract.md §7.2) — approvers sharing
38	   * a stageOrder run together (unanimous) before the next-lowest outstanding stage opens. Every
39	   * other mode is single-stage and ignores this (sent as 0, harmless). */
40	  stageOrder: number;
41	}
42	
43	/** Display-ready row — SelectorRow plus a resolved label/code and a composite key, since a bare
44	 * numeric id would collide across types (e.g. employeeId 3 and roleId 3 are unrelated). */
45	interface SelectedApproverRow extends SelectorRow {
46	  key: string;
47	  /** Mirrors selectorId when selectorType is 'employee' (the only kind the existing payload's
48	   * employeeId field understands); 0 for every other kind. */
49	  employeeId: number;
50	  label: string;
51	  code: string;
52	}
53	
54	@Component({
55	  selector: 'app-form',
56	  standalone: true,
57	  imports: [
58	    DxSelectBoxModule,
59	    DxCheckBoxModule,
60	    DxTagBoxModule,
61	    DxButtonModule,
62	    DxNumberBoxModule,
63	    ReactiveFormsModule,
64	    DxTemplateModule,
65	    FormControlPopoutComponent,
66	  ],
67	  templateUrl: './form.html',
68	  styleUrl: './form.scss',
69	})
70	export class Form implements OnInit {
71	  // Finalized frontend modes discussed with client.
72	  readonly APPROVAL_MODES = {
73	    DEFAULT_CHAIN: 'default_chain' as ApprovalMode,
74	    ANY_ONE: 'any_one' as ApprovalMode,
75	    SELECTED_EMPLOYEE_OVERRIDE: 'selected_employee_override' as ApprovalMode,
76	    // Exact string, verbatim from backend — Approval-Engine-API-Contract.md §7.1. Don't confuse
77	    // with "FirstDecisionWins" (PascalCase), which is a different, read-only stageGroupMode value
78	    // in GetInstanceTimeline responses, never something this screen sends.
79	    FIRST_DECISION_WINS: 'first_decision_wins' as ApprovalMode,
80	  };
81	
82	  travelConfigForm!: FormGroup;
83	  showPopup = false;
84	  screenName = 'travelconfig';
85	
86	  employees: any[] = [];
87	  roles: any[] = [];
88	  departments: any[] = [];
89	  designations: any[] = [];
90	  activeSelectorType: SelectorType = 'employee';
91	  selectorTypeOptions: { id: SelectorType; label: string }[] = [
92	    { id: 'employee', label: 'Employee' },
93	    { id: 'role', label: 'Role' },
94	    { id: 'department', label: 'Department' },
95	    { id: 'designation', label: 'Designation' },
96	  ];
97	  branches: { id: number; displayName: string }[] = [];
98	  formList: any[] = [];
99	  private allFormOptions: any[] = [];
100	  usedScopeKeys = new Set<string>();
101	
102	  /** Cross-module form docs now come from the shared FormDocMaster catalogue (see
103	   * docs/specs/Approval-Engine-API-Contract.md §3/§7) instead of a travel-only list, so the
104	   * dropdown needs a Module filter to stay usable as more modules get onboarded.
105	   * Wrapped as {key} objects with an explicit displayExpr/valueExpr (matching Branch/Form Type
106	   * below) rather than a raw primitive-string array — dx-select-box's _getPlainItems() reads
107	   * `this.option('items')` on every input repaint, and a bare primitive array with no expr is an
108	   * untested combination in this codebase that trips a "items.flatMap is not a function" crash. */
109	  moduleOptions: { key: string }[] = [];
110	  selectedModuleKey: string | null = null;
111	  /** Immutable scope after create — branch/form cannot change on edit. */
112	  private lockedScope: { companyMasterId: number; branchMasterId: number; formDocNo: number } | null =
113	    null;
114	
115	  isEditMode = false;
116	  configId = 0;
117	  formSubmitted = false;
118	
119	  // Master list of approver rows — covers every selector type. Replaces the old "ids array + meta
120	  // map keyed by employeeId" split now that rows can name an employee OR a role/department/
121	  // designation group (see SelectorType above); a plain numeric id can't be the key any more since
122	  // the same number means different things across types.
123	  selectorRows: SelectorRow[] = [];
124	  // Label/code captured from the backend at hydration time (employeeName/groupName on the raw API
125	  // row), used until the matching source list (employees/roles/departments/designations) finishes
126	  // loading. Keyed by selectorKey().
127	  private pendingRowLabels: Record<string, string> = {};
128	
129	  // Optional details editor for one selected row at a time, keyed by selectorKey().
130	  editingKey: string | null = null;
131	  editorDraft: { designation?: string; approvalType?: string } = { designation: '', approvalType: '' };
132	
133	  // ResolveSelector preview per selector type (Approval-Admin-Override-And-Group-Selectors-API-
134	  // Contract.md §3) — lets the admin see who a role/department/designation currently resolves to,
135	  // and how many of them have no login (so can never actually be asked to approve), before saving.
136	  selectorPreview: Partial<
137	    Record<
138	      SelectorType,
139	      {
140	        groups: {
141	          selectorId: number;
142	          groupName: string;
143	          employeeCount: number;
144	          withoutLoginCount: number;
145	        }[];
146	        employees: { employeeId: number; employeeName: string; employeeCode: string; hasLoginUser: boolean }[];
147	        withoutLoginCount: number;
148	      }
149	    >
150	  > = {};
151	  selectorPreviewLoading: Partial<Record<SelectorType, boolean>> = {};
152	  // Debounce timer + in-flight key per type — see refreshSelectorPreview's note below.
153	  private selectorPreviewDebounce: Partial<Record<SelectorType, ReturnType<typeof setTimeout>>> = {};
154	  private selectorPreviewInFlightKey: Partial<Record<SelectorType, string>> = {};
155	  // Frontend-Spec.md §1.2 — "show the merged employees list in an expandable panel".
156	  previewExpanded: Partial<Record<SelectorType, boolean>> = {};
157	
158	  approvalModeOptions = [
159	    {
160	      id: this.APPROVAL_MODES.DEFAULT_CHAIN,
161	      title: 'Default',
162	      description: 'Reporting Manager, then staged approvers in order.',
163	    },
164	    {
165	      id: this.APPROVAL_MODES.ANY_ONE,
166	      title: 'Any One',
167	      description: 'Any selected employee can approve.',
168	    },
169	    {
170	      id: this.APPROVAL_MODES.SELECTED_EMPLOYEE_OVERRIDE,
171	      title: 'Specific Employee',
172	      description: 'Only selected employees can approve.',
173	    },
174	    {
175	      id: this.APPROVAL_MODES.FIRST_DECISION_WINS,
176	      title: 'First Decision',
177	      description: 'Reporting Manager and/or selected employees race — first to decide wins.',
178	    },
179	  ];
180	
181	  constructor(
182	    private fb: FormBuilder,
183	    private apiService: ApiService,
184	    private route: ActivatedRoute,
185	    private router: Router,
186	    private toaster: ToastService,
187	    private authService: AuthService,
188	    private rbacService: RbacService,
189	  ) {}
190	
191	  ngOnInit(): void {
192	    this.initForm();
193	    this.loadInitialCompanyBranch();
194	    this.getFormList();
195	    this.loadSelectorGroups();
196	
197	    this.route.paramMap.subscribe((params) => {
198	      const id = params.get('id');
199	      if (!id) return;
200	      this.isEditMode = true;
201	      this.configId = Number(id);
202	      this.getById(this.configId);
203	    });
204	  }
205	
206	  initForm(): void {
207	    this.travelConfigForm = this.fb.group({
208	      id: [null],
209	      companyMasterId: [null, Validators.required],
210	      branchMasterId: [null, Validators.required],
211	      formDocNo: [null, Validators.required],
212	      approvalMode: [this.APPROVAL_MODES.DEFAULT_CHAIN, Validators.required],
213	      // default_chain / any_one / first_decision_wins: admin can toggle.
214	      // selected_employee_override: forced false + disabled, see applyReportingManagerControlState.
215	      isReportingMgrRequired: [true],
216	      // Optional. Who the engine should route to when an employee's own ReportingPersonID is null
217	      // (nothing to resolve) — see docs/specs/Fallback-Reporting-Manager-Backend-Spec.md. Frontend
218	      // only collects/displays this; the actual substitution happens backend-side.
219	      fallbackApproverId: [null],
220	    });
221	
222	    this.travelConfigForm.get('approvalMode')?.valueChanges.subscribe((mode: ApprovalMode) => {
223	      this.applyReportingManagerControlState(mode);
224	    });
225	    this.applyReportingManagerControlState(this.APPROVAL_MODES.DEFAULT_CHAIN);
226	
227	    this.travelConfigForm.get('branchMasterId')?.valueChanges.subscribe((branchId) => {
228	      if (branchId) {
229	        this.reloadBranchEmployees(Number(branchId));
230	        if (!this.isEditMode) this.applyFormListFilter();
231	      }
232	    });
233	  }
234	
235	  private loadInitialCompanyBranch(): void {
236	    const companyId = this.authService.getCompanyId();
237	    if (!companyId) return;
238	    this.travelConfigForm.patchValue({ companyMasterId: companyId }, { emitEvent: false });
239	    this.apiService.get(`/api/TravelPayment/GetAllBranches/${companyId}`).subscribe((res: any) => {
240	      const data = res?.data ?? res?.Data ?? [];
241	      this.branches = (data as any[]).map((b) => ({
242	        id: Number(b.unitMasterId ?? b.id ?? b.branchId),
243	        displayName: `${b.name ?? b.branchName} (${b.code ?? b.branchCode})`,
244	      }));
245	      const branchId = this.authService.getBranchId();
246	      const selected = this.branches.find((b) => b.id === branchId) ?? this.branches[0];
247	      if (selected) {
248	        this.travelConfigForm.patchValue({ branchMasterId: selected.id });
249	      }
250	      this.loadUsedScopes();
251	    });
252	  }
253	
254	  onBranchChanged(branchId?: number | null): void {
255	    const branch = Number(branchId ?? this.travelConfigForm.get('branchMasterId')?.value ?? 0);
256	    if (branch > 0) {
257	      this.clearBranchScopedApproverSelections();
258	      this.getEmployeeList(branch);
259	    } else {
260	      this.employees = [];
261	    }
262	    this.loadUsedScopes();
263	    if (!this.isEditMode) this.applyFormListFilter();
264	  }
265	
266	  /** Only employee rows are branch-scoped (the employee list itself is fetched per-branch) — role/
267	   * department/designation selections are org-wide groupings via RBAC, so a branch change leaves
268	   * them untouched. */
269	  private clearBranchScopedApproverSelections(): void {
270	    this.selectorRows = this.selectorRows.filter((row) => row.selectorType !== 'employee');
271	    if (this.editingKey?.startsWith('employee:')) this.cancelApproverDetailsEdit();
272	  }
273	
274	  private selectorKey(selectorType: SelectorType, selectorId: number): string {
275	    return `${selectorType}:${selectorId}`;
276	  }
277	
278	  selectorTypeLabel(type: SelectorType): string {
279	    return this.selectorTypeOptions.find((o) => o.id === type)?.label ?? type;
280	  }
281	
282	  setActiveSelectorType(type: SelectorType): void {
283	    this.activeSelectorType = type;
284	  }
285	
286	  private loadSelectorGroups(): void {
287	    this.rbacService.getRoles().subscribe({
288	      next: (res: any) => {
289	        if (res?.isSuccess) this.roles = res.data ?? [];
290	      },
291	      error: (err) => console.error('Error loading roles for approver selector:', err),
292	    });
293	    this.rbacService.getDepartments().subscribe({
294	      next: (res: any) => {
295	        if (res?.isSuccess) {
296	          this.departments = (res.data ?? []).map((d: any) => ({
297	            id: Number(d.id ?? d.Id),
298	            name: d.name ?? d.Name,
299	          }));
300	        }
301	      },
302	      error: (err) => console.error('Error loading departments for approver selector:', err),
303	    });
304	    this.rbacService.getDesignations().subscribe({
305	      next: (res: any) => {
306	        if (res?.isSuccess) {
307	          this.designations = (res.data ?? []).map((d: any) => ({
308	            id: Number(d.id ?? d.Id),
309	            name: d.name ?? d.Name,
310	          }));
311	        }
312	      },
313	      error: (err) => console.error('Error loading designations for approver selector:', err),
314	    });
315	  }
316	
317	  /** Items for the currently active selector-type's tag-box — one shared {id, label, code} shape
318	   * regardless of underlying source list, so the template doesn't need a template per type.
319	   *
320	   * Same bug family as activeSelectorValue below: this used to .map() a brand-new array of
321	   * brand-new object literals on every single read. Angular re-reads it on every change-detection
322	   * pass and rebinds dx-tag-box's [items] to that new reference even when the underlying
323	   * roles/departments/designations/employees list hasn't changed — DevExtreme treats a new
324	   * `items`/dataSource reference as "the data changed under you" and resets the open dropdown's
325	   * internal state, which can silently discard the click the user just made (reported 2026-10-10:
326	   * "unable to select any roles/department/designation" — the employee tag-box happened to dodge
327	   * this in practice since this screen's extra role/department/designation-only UI, like the
328	   * resolve preview below, triggers change detection far more often). Cached per selector type,
329	   * keyed on the *source array's own reference* (this.roles/this.departments/... are only ever
330	   * reassigned once per network response, never recreated per read) — so as long as the source
331	   * hasn't actually changed, the exact same output array/objects are returned every time. */
332	  private _activeSelectorItemsCache: Partial<
333	    Record<SelectorType, { source: any[]; items: { id: number; label: string; code?: string }[] }>
334	  > = {};
335	
336	  get activeSelectorItems(): { id: number; label: string; code?: string }[] {
337	    const type = this.activeSelectorType;
338	    const source =
339	      type === 'role'
340	        ? this.roles
341	        : type === 'department'
342	          ? this.departments
343	          : type === 'designation'
344	            ? this.designations
345	            : this.employees;
346	
347	    const cached = this._activeSelectorItemsCache[type];
348	    if (cached && cached.source === source) return cached.items;
349	
350	    const items = this.computeActiveSelectorItems(type, source);
351	    this._activeSelectorItemsCache[type] = { source, items };
352	    return items;
353	  }
354	
355	  private computeActiveSelectorItems(
356	    type: SelectorType,
357	    source: any[],
358	  ): { id: number; label: string; code?: string }[] {
359	    switch (type) {
360	      case 'role':
361	        return source.map((r: any) => ({
362	          id: Number(r.roleId ?? r.id),
363	          label: r.roleName ?? r.name ?? `Role #${r.roleId ?? r.id}`,
364	        }));
365	      case 'department':
366	      case 'designation':
367	        return source.map((d: any) => ({ id: d.id, label: d.name }));
368	      default:
369	        return source.map((e: any) => ({
370	          id: Number(e.employeeMasterID),
371	          label: `${e.firstName ?? ''} ${e.lastName ?? ''}`.trim(),
372	          code: e.code,
373	        }));
374	    }
375	  }
376	
377	  // Bug (reported 2026-10-10): this getter used to build a brand-new array on every read. Angular
378	  // re-reads it on every change-detection pass and rebinds dx-tag-box's [value] to that new
379	  // reference even when the ids are identical; DevExtreme treats that as an external value change
380	  // and echoes onValueChanged, which rebuilt selectorRows and re-fetched ResolveSelector, which
381	  // changed selectorPreview/pendingRowLabels, triggering another CD pass — an infinite loop (435
382	  // calls/burst logged in production). Returning the SAME array instance when the underlying ids
383	  // haven't actually changed breaks that cycle at the source.
384	  private _activeSelectorValueCache: number[] = [];
385	  private _activeSelectorValueCacheKey = '';
386	
387	  get activeSelectorValue(): number[] {
388	    const ids = this.selectorRows
389	      .filter((r) => r.selectorType === this.activeSelectorType)
390	      .map((r) => r.selectorId)
391	      .sort((a, b) => a - b);
392	    const key = `${this.activeSelectorType}:${ids.join(',')}`;
393	    if (key !== this._activeSelectorValueCacheKey) {
394	      this._activeSelectorValueCacheKey = key;
395	      this._activeSelectorValueCache = ids;
396	    }
397	    return this._activeSelectorValueCache;
398	  }
399	
400	  /** Diffs the active type's tag-box selection against selectorRows, touching only rows of that
401	   * type — rows of every other type are left exactly as they were, so switching the toggle and
402	   * picking from a different list is additive, not a replacement. */
403	  onActiveSelectorChanged(ids: number[]): void {
404	    const type = this.activeSelectorType;
405	    const safeIds = (ids ?? []).map((x) => Number(x)).filter((x) => Number.isFinite(x) && x > 0);
406	
407	    // Echo guard: DevExtreme can re-fire onValueChanged for a [value] rebind that didn't actually
408	    // change the selection (see activeSelectorValue's note above) — bail out before touching
409	    // selectorRows or firing a preview request when the incoming set is identical to what's
410	    // already stored, order ignored.
411	    const currentIds = this.selectorRows
412	      .filter((r) => r.selectorType === type)
413	      .map((r) => r.selectorId);
414	    const sortedIncoming = [...safeIds].sort((a, b) => a - b);
415	    const sortedCurrent = [...currentIds].sort((a, b) => a - b);
416	    const isSameSet =
417	      sortedIncoming.length === sortedCurrent.length &&
418	      sortedIncoming.every((id, i) => id === sortedCurrent[i]);
419	    if (isSameSet) return;
420	
421	    const otherRows = this.selectorRows.filter((r) => r.selectorType !== type);
422	    const existingByType = new Map(
423	      this.selectorRows.filter((r) => r.selectorType === type).map((r) => [r.selectorId, r]),
424	    );
425	    const nextTypeRows: SelectorRow[] = safeIds.map(
426	      (id) => existingByType.get(id) ?? { selectorType: type, selectorId: id, stageOrder: 0 },
427	    );
428	    this.selectorRows = [...otherRows, ...nextTypeRows];
429	
430	    if (
431	      this.editingKey &&
432	      !this.selectorRows.some((r) => this.selectorKey(r.selectorType, r.selectorId) === this.editingKey)
433	    ) {
434	      this.cancelApproverDetailsEdit();
435	    }
436	
437	    if (type !== 'employee') this.refreshSelectorPreview(type);
438	  }
439	
440	  /** "Select all" convenience (Frontend-Spec.md §1.1) — ticks every option currently in the active
441	   * type's list. UI convenience only: the backend stores exactly these rows, so a group created
442	   * later is NOT retroactively included — see the helper text next to this in the template. */
443	  selectAllActiveSelectorItems(): void {
444	    this.onActiveSelectorChanged(this.activeSelectorItems.map((i) => i.id));
445	  }
446	
447	  clearActiveSelectorItems(): void {
448	    this.onActiveSelectorChanged([]);
449	  }
450	
451	  /** Group selectors work for every form doc, Travel Management included (Approval-Admin-Override-
452	   * And-Group-Selectors-API-Contract.md §3, confirmed §4). Kept only to drive the Travel-specific
453	   * "fin" label hint below — Settlement/Advance-Payment visibility for a group row on a Travel
454	   * Advance Payment config requires its approvalType label to contain "fin" (§4's last bullet). */
455	  get isTravelManagementForm(): boolean {
456	    const formDocNo = Number(this.travelConfigForm?.get('formDocNo')?.value ?? 0);
457	    if (!formDocNo) return false;
458	    const doc = this.allFormOptions.find((f: any) => Number(f.id) === formDocNo);
459	    return !!doc?.moduleKey && /travel/i.test(`${doc.moduleKey}`);
460	  }
461	
462	  get activeSelectorPreview() {
463	    return this.selectorPreview[this.activeSelectorType] ?? null;
464	  }
465	
