479	  /** Calls ResolveSelector (§3 of the contract above) for every currently-selected id of one
480	   * selector type, so the admin sees real resolved employees/no-login counts before saving.
481	   * Dropped entirely (not fetched) for 'employee' rows — those are already named individuals.
482	   * Debounced (~300ms) and deduped by (type, sorted ids): onActiveSelectorChanged's echo guard
483	   * already stops most redundant calls, but "Select all"/rapid edits can still call this more than
484	   * once for the same effective selection before the previous request lands. */
485	  private refreshSelectorPreview(type: SelectorType): void {
486	    const ids = this.selectorRows
487	      .filter((r) => r.selectorType === type)
488	      .map((r) => r.selectorId)
489	      .sort((a, b) => a - b);
490	
491	    clearTimeout(this.selectorPreviewDebounce[type]);
492	
493	    if (!ids.length) {
494	      delete this.selectorPreview[type];
495	      delete this.selectorPreviewLoading[type];
496	      delete this.selectorPreviewInFlightKey[type];
497	      return;
498	    }
499	
500	    const key = ids.join(',');
501	    this.selectorPreviewDebounce[type] = setTimeout(() => {
502	      if (this.selectorPreviewInFlightKey[type] === key) return;
503	      this.selectorPreviewInFlightKey[type] = key;
504	      this.fetchSelectorPreview(type, key);
505	    }, 300);
506	  }
507	
508	  private fetchSelectorPreview(type: SelectorType, idsCsv: string): void {
509	    this.selectorPreviewLoading[type] = true;
510	    this.apiService
511	      .get(`/api/Approval/ResolveSelector?selectorType=${type}&selectorIds=${idsCsv}`)
512	      .subscribe({
513	        next: (res: any) => {
514	          this.selectorPreviewLoading[type] = false;
515	          if (this.selectorPreviewInFlightKey[type] === idsCsv) delete this.selectorPreviewInFlightKey[type];
516	          if (!res?.isSuccess || !res.data) return;
517	
518	          const groups = (res.data.groups ?? []).map((g: any) => ({
519	            selectorId: Number(g.selectorId),
520	            groupName: g.groupName ?? `${this.selectorTypeLabel(type)} #${g.selectorId}`,
521	            employeeCount: Array.isArray(g.employees) ? g.employees.length : 0,
522	            withoutLoginCount: Number(g.withoutLoginCount ?? 0),
523	          }));
524	          const employees = (res.data.employees ?? []).map((e: any) => ({
525	            employeeId: Number(e.employeeId),
526	            employeeName: e.employeeName ?? `Emp#${e.employeeId}`,
527	            employeeCode: e.employeeCode ?? '',
528	            hasLoginUser: !!e.hasLoginUser,
529	          }));
530	          this.selectorPreview[type] = {
531	            groups,
532	            employees,
533	            withoutLoginCount: Number(res.data.withoutLoginCount ?? 0),
534	          };
535	          // Backfill real group names immediately instead of waiting on employees/roles/
536	          // departments/designations (which don't carry a resolved member count anyway).
537	          groups.forEach((g: any) => {
538	            this.pendingRowLabels[this.selectorKey(type, g.selectorId)] = g.groupName;
539	          });
540	        },
541	        error: (err) => {
542	          this.selectorPreviewLoading[type] = false;
543	          if (this.selectorPreviewInFlightKey[type] === idsCsv) delete this.selectorPreviewInFlightKey[type];
544	          const status = err?.status;
545	          if (status === 403) {
546	            // Frontend-Spec.md §1.2 — hide rather than error; this whole screen is admin
547	            // territory anyway, so a 403 here means the caller shouldn't be on this form at all.
548	            delete this.selectorPreview[type];
549	            return;
550	          }
551	          if (status === 404) {
552	            // A selected id no longer exists — drop it and refresh the picker's option list.
553	            this.selectorRows = this.selectorRows.filter((r) => r.selectorType !== type);
554	            delete this.selectorPreview[type];
555	            this.toaster.warning(
556	              `One or more selected ${this.selectorTypeLabel(type).toLowerCase()}s no longer exist and were removed.`,
557	            );
558	            return;
559	          }
560	          console.error(`Error resolving ${type} selector preview:`, err);
561	        },
562	      });
563	  }
