709	  /** Default-chain-only grouping preview: approvers sharing a stageOrder run together, ordered
710	   * lowest stage first. Per the contract above, a stage containing any role/department/designation
711	   * row becomes AnyOne (any one resolved member, or any named employee in that stage, can approve);
712	   * a stage of only named employees stays Unanimous, same as before. */
713	  get stageGroupsPreview(): { stageOrder: number; names: string[]; isAnyOne: boolean }[] {
714	    const byStage = new Map<number, { names: string[]; isAnyOne: boolean }>();
