816	    }
817	
818	    if (this.isEditMode && this.lockedScope) {
819	      if (
820	        Number(v.companyMasterId) !== this.lockedScope.companyMasterId ||
821	        Number(v.branchMasterId) !== this.lockedScope.branchMasterId ||
822	        Number(v.formDocNo) !== this.lockedScope.formDocNo
823	      ) {
