959	  /** Pre-§7.2 configs only ever set these two fixed-role fields — the DTO still accepts them but
960	   * the engine no longer reads them for default_chain (Approval-Engine-API-Contract.md §7.2), so
961	   * synthesize equivalent selectedApprovers rows here purely so this screen keeps showing them,
962	   * and so the next Save carries them forward correctly under the new model instead of silently
963	   * losing them. Only kicks in when the backend hasn't already returned real selectedApprovers
964	   * rows for this config. */
965	  private withLegacyDefaultChainFallback(mode: ApprovalMode, data: any): any[] {
966	    const apiRows: any[] = Array.isArray(data?.selectedApprovers) ? data.selectedApprovers : [];
967	    if (mode !== this.APPROVAL_MODES.DEFAULT_CHAIN || apiRows.length) return apiRows;
968	
969	    const synthesized: any[] = [];
970	    const financeId = Number(data?.financeApproverId ?? data?.FinanceApproverId ?? 0);
971	    if (data?.isFinanceApproverRequired && financeId > 0) {
972	      synthesized.push({ employeeId: financeId, approvalType: 'Finance', stageOrder: 0 });
973	    }
974	    const hrId = Number(data?.hrApproverId ?? data?.HrApproverId ?? 0);
975	    if (data?.isHrRequired && hrId > 0) {
976	      synthesized.push({ employeeId: hrId, approvalType: 'HR', stageOrder: 0 });
977	    }
978	    return synthesized;
979	  }
