981	  /** Edit mode: branch + form are fixed after create to avoid duplicate/conflicting configs. */
982	  private lockScopeFieldsAfterLoad(): void {
983	    if (!this.isEditMode) return;
984	
985	    // Derives the Module filter from the now-loaded formDocNo, regardless of whether
986	    // getFormList() resolved before or after this getById() callback.
987	    this.applyFormListFilter();
988	
989	    const companyId = Number(this.travelConfigForm.get('companyMasterId')?.value ?? 0);
990	    const branchId = Number(this.travelConfigForm.get('branchMasterId')?.value ?? 0);
991	    const formDocNo = Number(this.travelConfigForm.get('formDocNo')?.value ?? 0);
992	    if (companyId > 0 && branchId > 0 && formDocNo > 0) {
993	      this.lockedScope = { companyMasterId: companyId, branchMasterId: branchId, formDocNo };
994	    }
995	
996	    this.travelConfigForm.get('branchMasterId')?.disable({ emitEvent: false });
997	    this.travelConfigForm.get('formDocNo')?.disable({ emitEvent: false });
998	
999	    const currentForm = this.allFormOptions.find((f) => Number(f.id) === formDocNo);
1000	    if (currentForm && !this.formList.some((f) => Number(f.id) === formDocNo)) {
1001	      this.formList = [...this.formList, currentForm];
1002	    }
1003	  }
1004	
1005	  get lockedBranchLabel(): string {
1006	    const branchId = this.lockedScope?.branchMasterId;
1007	    if (!branchId) return '—';
1008	    return this.branches.find((b) => b.id === branchId)?.displayName ?? `Branch #${branchId}`;
1009	  }
1010	
1011	  save(): void {
1012	    this.formSubmitted = true;
1013	    this.travelConfigForm.markAllAsTouched();
1014	
1015	    const clientError = this.validateBeforeSave();
1016	    if (clientError) {
1017	      this.toaster.warning(clientError);
1018	      return;
1019	    }
1020	
1021	    if (this.travelConfigForm.invalid) {
1022	      this.toaster.warning('Please fill all required fields.');
1023	      return;
1024	    }
1025	
1026	    const apiPayload = this.buildApiPayload();
1027	
1028	    if (this.isEditMode) {
1029	      this.apiService.put('/api/TravelConfig/Update', apiPayload).subscribe({
1030	        next: (res: any) => this.handleSaveResponse(res, 'update'),
1031	        error: (err) => this.handleSaveError(err, 'update'),
1032	      });
1033	    } else {
1034	      this.apiService.post('/api/TravelConfig/Insert', apiPayload).subscribe({
1035	        next: (res: any) => this.handleSaveResponse(res, 'insert'),
1036	        error: (err) => this.handleSaveError(err, 'insert'),
1037	      });
1038	    }
1039	  }
1040	
1041	  private handleSaveResponse(res: any, mode: 'insert' | 'update'): void {
1042	    if (res?.isSuccess) {
1043	      this.toaster.success(
1044	        res.message ?? (mode === 'insert' ? 'Saved successfully' : 'Updated successfully'),
1045	      );
1046	      this.router.navigate(['/admin/hr-config']);
1047	      return;
1048	    }
1049	    this.toaster.error(
1050	      res?.message ??
1051	        (mode === 'insert'
1052	          ? 'Could not save configuration.'
1053	          : 'Could not update configuration.'),
1054	    );
1055	  }
1056	
1057	  private handleSaveError(err: any, mode: 'insert' | 'update'): void {
1058	    const msg =
1059	      err?.error?.message ??
1060	      (mode === 'insert' ? 'Could not save configuration.' : 'Could not update configuration.');
1061	    this.toaster.error(msg);
1062	  }
1063	
1064	  /**
1065	   * API contract mapper (Approval-Engine-API-Contract.md §7.2): every mode now sends the same
1066	   * generic selectedApprovers array; the old fixed-role Finance/HR fields are retired here (the
1067	   * DTO still accepts them, but the engine no longer reads them for default_chain, so there's
1068	   * nothing to gain by still sending them).
1069	   */
1070	  private buildApiPayload(): any {
1071	    const formValue = this.travelConfigForm.getRawValue();
1072	    return {
1073	      id: formValue.id,
1074	      companyMasterId: Number(formValue.companyMasterId),
1075	      branchMasterId: Number(formValue.branchMasterId),
1076	      formDocNo: formValue.formDocNo,
1077	      approvalMode: this.normalizeApprovalMode(formValue.approvalMode),
1078	      isReportingMgrRequired: !!formValue.isReportingMgrRequired,
1079	      // Null, not 0, when unset — 0 isn't a real employee id and would read as "resolved" instead
1080	      // of "not configured" on the backend side.
1081	      fallbackApproverId: Number(formValue.fallbackApproverId) || null,
1082	      selectedApprovers: this.buildSelectedApproversForPayload(),
1083	    };
1084	  }
1085	
1086	  private normalizeApprovalMode(rawMode: unknown): ApprovalMode {
1087	    const value = `${rawMode ?? ''}`.trim().toLowerCase() as ApprovalMode;
1088	    if (value === this.APPROVAL_MODES.ANY_ONE) return this.APPROVAL_MODES.ANY_ONE;
1089	    if (value === this.APPROVAL_MODES.SELECTED_EMPLOYEE_OVERRIDE) {
1090	      return this.APPROVAL_MODES.SELECTED_EMPLOYEE_OVERRIDE;
1091	    }
1092	    if (value === this.APPROVAL_MODES.FIRST_DECISION_WINS) return this.APPROVAL_MODES.FIRST_DECISION_WINS;
1093	    return this.APPROVAL_MODES.DEFAULT_CHAIN;
1094	  }
1095	
1096	  private applyReportingManagerControlState(mode: ApprovalMode): void {
1097	    const rmCtrl = this.travelConfigForm.get('isReportingMgrRequired');
1098	    if (!rmCtrl) return;
1099	
1100	    if (mode === this.APPROVAL_MODES.SELECTED_EMPLOYEE_OVERRIDE) {
1101	      // "In specific Employee, we do not give reporting manager check!"
1102	      rmCtrl.setValue(false, { emitEvent: false });
1103	      rmCtrl.disable({ emitEvent: false });
1104	      return;
1105	    }
1106	
1107	    // Default Chain, Any One and First Decision Wins all allow toggling.
1108	    rmCtrl.enable({ emitEvent: false });
1109	  }
1110	
1111	  /** Same generic row shape for every mode now (Approval-Engine-API-Contract.md §7.2), extended
1112	   * with selectorType/selectorId (Approval-Admin-Override-And-Group-Selectors-API-Contract.md §3)
1113	   * — stageOrder only means something for default_chain, every other mode ignores it server-side.
1114	   * Group rows (non-'employee') work for every form doc, Travel Management included — but on a
1115	   * Travel Advance Payment config, only a row whose approvalType label contains "fin" also grants
1116	   * Settlement/Payment-screen visibility (§4's last bullet) — see isTravelManagementForm's helper
1117	   * text in the template. */
1118	  private buildSelectedApproversForPayload(): any[] {
1119	    return this.selectorRows
1120	      .filter((row) => row.selectorId > 0)
1121	      .map((row) => ({
1122	        selectorType: row.selectorType,
1123	        selectorId: row.selectorId,
1124	        employeeId: row.selectorType === 'employee' ? row.selectorId : undefined,
1125	        designation: row.designation || undefined,
1126	        approvalType: row.approvalType || undefined,
1127	        stageOrder: row.stageOrder ?? 0,
1128	      }));
1129	  }
1130	
1131	  private hydrateSelectedApprovers(apiRows: any[]): void {
1132	    this.pendingRowLabels = {};
1133	
1134	    this.selectorRows = (apiRows ?? [])
1135	      .map((r: any): SelectorRow | null => {
1136	        const selectorType: SelectorType = (r.selectorType ?? r.SelectorType ?? 'employee') as SelectorType;
1137	        const selectorId = Number(
1138	          selectorType === 'employee' ? (r.employeeId ?? r.EmployeeId) : (r.selectorId ?? r.SelectorId),
1139	        );
1140	        if (!Number.isFinite(selectorId) || selectorId <= 0) return null;
1141	
1142	        // selectorName is the backend's resolved label for group rows (Approval-Admin-Override-
1143	        // And-Group-Selectors-API-Contract.md §3's GetAll/GetById reads); employeeName/groupName
1144	        // covered the pre-contract-finalization shape and stay as a fallback.
1145	        const cachedLabel = `${
1146	          r.selectorName ?? r.SelectorName ?? r.employeeName ?? r.EmployeeName ?? r.groupName ?? r.GroupName ?? ''
1147	        }`.trim();
1148	        if (cachedLabel) this.pendingRowLabels[this.selectorKey(selectorType, selectorId)] = cachedLabel;
1149	
1150	        return {
1151	          selectorType,
1152	          selectorId,
1153	          designation: `${r.designation ?? r.Designation ?? ''}`.trim() || undefined,
1154	          approvalType: `${r.approvalType ?? r.ApprovalType ?? ''}`.trim() || undefined,
1155	          stageOrder: Number(r.stageOrder ?? r.StageOrder ?? 0) || 0,
1156	        };
1157	      })
1158	      .filter((r): r is SelectorRow => r !== null);
1159	
1160	    const typesToPreview = new Set(
1161	      this.selectorRows.map((r) => r.selectorType).filter((t) => t !== 'employee'),
1162	    );
1163	    typesToPreview.forEach((t) => this.refreshSelectorPreview(t));
1164	  }
1165	
1166	  private normalizeLookupEmployees(res: any): any[] {
1167	    const source = res?.users ?? res?.data ?? [];
1168	    if (!Array.isArray(source)) return [];
1169	    return source.map((e: any) => ({
1170	      employeeMasterID: Number(e.employeeMasterId ?? e.EmployeeMasterId ?? e.employeeMasterID ?? e.EmployeeMasterID ?? e.id ?? e.Id ?? 0),
1171	      firstName: e.firstName ?? e.FirstName ?? '',
1172	      lastName: e.lastName ?? e.LastName ?? '',
1173	      code: e.code ?? e.Code ?? '',
1174	    }));
1175	  }
