import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { ApiService } from '../../../../services/api.service';
import { ToastService } from '../../../../services/toaster.service';
import {
  DxButtonModule,
  DxCheckBoxModule,
  DxNumberBoxModule,
  DxSelectBoxModule,
  DxTagBoxModule,
  DxTemplateModule,
} from 'devextreme-angular';
import { FormControlPopoutComponent } from '../../../../layout/formcontrol-popout/formcontrol-popout.component';
import { AuthService } from '../../../../services/auth.service';
import { RbacService } from '../../rbac/services/rbac.service';

type ApprovalMode =
  | 'default_chain'
  | 'any_one'
  | 'selected_employee_override'
  | 'first_decision_wins';

/** Who an approver row actually names. Backend support for all four kinds is live
 * (hrmsystembe/Specs/Approval-Admin-Override-And-Group-Selectors-API-Contract.md §3) — a role/
 * department/designation row resolves once, when the approval instance is created, to that group's
 * then-current active employees with an active login; not re-evaluated against already-pending
 * steps. A stage (rows sharing a stageOrder) containing any such row becomes AnyOne instead of
 * Unanimous — see stageGroupsPreview. Works for every form doc, Travel Management included. */
type SelectorType = 'employee' | 'role' | 'department' | 'designation';

interface SelectorRow {
  selectorType: SelectorType;
  selectorId: number;
  designation?: string;
  approvalType?: string;
  /** Only meaningful for default_chain (Approval-Engine-API-Contract.md §7.2) — approvers sharing
   * a stageOrder run together (unanimous) before the next-lowest outstanding stage opens. Every
   * other mode is single-stage and ignores this (sent as 0, harmless). */
  stageOrder: number;
}

/** Display-ready row — SelectorRow plus a resolved label/code and a composite key, since a bare
 * numeric id would collide across types (e.g. employeeId 3 and roleId 3 are unrelated). */
interface SelectedApproverRow extends SelectorRow {
  key: string;
  /** Mirrors selectorId when selectorType is 'employee' (the only kind the existing payload's
   * employeeId field understands); 0 for every other kind. */
  employeeId: number;
  label: string;
  code: string;
}

@Component({
  selector: 'app-form',
  standalone: true,
  imports: [
    DxSelectBoxModule,
    DxCheckBoxModule,
    DxTagBoxModule,
    DxButtonModule,
    DxNumberBoxModule,
    ReactiveFormsModule,
    DxTemplateModule,
    FormControlPopoutComponent,
  ],
  templateUrl: './form.html',
  styleUrl: './form.scss',
})
export class Form implements OnInit {
  // Finalized frontend modes discussed with client.
  readonly APPROVAL_MODES = {
    DEFAULT_CHAIN: 'default_chain' as ApprovalMode,
    ANY_ONE: 'any_one' as ApprovalMode,
    SELECTED_EMPLOYEE_OVERRIDE: 'selected_employee_override' as ApprovalMode,
    // Exact string, verbatim from backend — Approval-Engine-API-Contract.md §7.1. Don't confuse
    // with "FirstDecisionWins" (PascalCase), which is a different, read-only stageGroupMode value
    // in GetInstanceTimeline responses, never something this screen sends.
    FIRST_DECISION_WINS: 'first_decision_wins' as ApprovalMode,
  };

  travelConfigForm!: FormGroup;
  showPopup = false;
  screenName = 'travelconfig';

  employees: any[] = [];
  roles: any[] = [];
  departments: any[] = [];
  designations: any[] = [];
  activeSelectorType: SelectorType = 'employee';
  selectorTypeOptions: { id: SelectorType; label: string }[] = [
    { id: 'employee', label: 'Employee' },
    { id: 'role', label: 'Role' },
    { id: 'department', label: 'Department' },
    { id: 'designation', label: 'Designation' },
  ];
  branches: { id: number; displayName: string }[] = [];
  formList: any[] = [];
  private allFormOptions: any[] = [];
  usedScopeKeys = new Set<string>();

  /** Cross-module form docs now come from the shared FormDocMaster catalogue (see
   * docs/specs/Approval-Engine-API-Contract.md §3/§7) instead of a travel-only list, so the
   * dropdown needs a Module filter to stay usable as more modules get onboarded.
   * Wrapped as {key} objects with an explicit displayExpr/valueExpr (matching Branch/Form Type
   * below) rather than a raw primitive-string array — dx-select-box's _getPlainItems() reads
   * `this.option('items')` on every input repaint, and a bare primitive array with no expr is an
   * untested combination in this codebase that trips a "items.flatMap is not a function" crash. */
  moduleOptions: { key: string }[] = [];
  selectedModuleKey: string | null = null;
  /** Immutable scope after create — branch/form cannot change on edit. */
  private lockedScope: { companyMasterId: number; branchMasterId: number; formDocNo: number } | null =
    null;

  isEditMode = false;
  configId = 0;
  formSubmitted = false;

  // Master list of approver rows — covers every selector type. Replaces the old "ids array + meta
  // map keyed by employeeId" split now that rows can name an employee OR a role/department/
  // designation group (see SelectorType above); a plain numeric id can't be the key any more since
  // the same number means different things across types.
  selectorRows: SelectorRow[] = [];
  // Label/code captured from the backend at hydration time (employeeName/groupName on the raw API
  // row), used until the matching source list (employees/roles/departments/designations) finishes
  // loading. Keyed by selectorKey().
  private pendingRowLabels: Record<string, string> = {};

  // Optional details editor for one selected row at a time, keyed by selectorKey().
  editingKey: string | null = null;
  editorDraft: { designation?: string; approvalType?: string } = { designation: '', approvalType: '' };

  // ResolveSelector preview per selector type (Approval-Admin-Override-And-Group-Selectors-API-
  // Contract.md §3) — lets the admin see who a role/department/designation currently resolves to,
  // and how many of them have no login (so can never actually be asked to approve), before saving.
  selectorPreview: Partial<
    Record<
      SelectorType,
      {
        groups: {
          selectorId: number;
          groupName: string;
          employeeCount: number;
          withoutLoginCount: number;
        }[];
        employees: { employeeId: number; employeeName: string; employeeCode: string; hasLoginUser: boolean }[];
        withoutLoginCount: number;
      }
    >
  > = {};
  selectorPreviewLoading: Partial<Record<SelectorType, boolean>> = {};
  // Debounce timer + in-flight key per type — see refreshSelectorPreview's note below.
  private selectorPreviewDebounce: Partial<Record<SelectorType, ReturnType<typeof setTimeout>>> = {};
  private selectorPreviewInFlightKey: Partial<Record<SelectorType, string>> = {};
  // Frontend-Spec.md §1.2 — "show the merged employees list in an expandable panel".
  previewExpanded: Partial<Record<SelectorType, boolean>> = {};

  approvalModeOptions = [
    {
      id: this.APPROVAL_MODES.DEFAULT_CHAIN,
      title: 'Default',
      description: 'Reporting Manager, then staged approvers in order.',
    },
    {
      id: this.APPROVAL_MODES.ANY_ONE,
      title: 'Any One',
      description: 'Any selected employee can approve.',
    },
    {
      id: this.APPROVAL_MODES.SELECTED_EMPLOYEE_OVERRIDE,
      title: 'Specific Employee',
      description: 'Only selected employees can approve.',
    },
    {
      id: this.APPROVAL_MODES.FIRST_DECISION_WINS,
      title: 'First Decision',
      description: 'Reporting Manager and/or selected employees race — first to decide wins.',
    },
  ];

  constructor(
    private fb: FormBuilder,
    private apiService: ApiService,
    private route: ActivatedRoute,
    private router: Router,
    private toaster: ToastService,
    private authService: AuthService,
    private rbacService: RbacService,
  ) {}

  ngOnInit(): void {
    this.initForm();
    this.loadInitialCompanyBranch();
    this.getFormList();
    this.loadSelectorGroups();

    this.route.paramMap.subscribe((params) => {
      const id = params.get('id');
      if (!id) return;
      this.isEditMode = true;
      this.configId = Number(id);
      this.getById(this.configId);
    });
  }

  initForm(): void {
    this.travelConfigForm = this.fb.group({
      id: [null],
      companyMasterId: [null, Validators.required],
      branchMasterId: [null, Validators.required],
      formDocNo: [null, Validators.required],
      approvalMode: [this.APPROVAL_MODES.DEFAULT_CHAIN, Validators.required],
      // default_chain / any_one / first_decision_wins: admin can toggle.
      // selected_employee_override: forced false + disabled, see applyReportingManagerControlState.
      isReportingMgrRequired: [true],
      // Optional. Who the engine should route to when an employee's own ReportingPersonID is null
      // (nothing to resolve) — see docs/specs/Fallback-Reporting-Manager-Backend-Spec.md. Frontend
      // only collects/displays this; the actual substitution happens backend-side.
      fallbackApproverId: [null],
    });

    this.travelConfigForm.get('approvalMode')?.valueChanges.subscribe((mode: ApprovalMode) => {
      this.applyReportingManagerControlState(mode);
    });
    this.applyReportingManagerControlState(this.APPROVAL_MODES.DEFAULT_CHAIN);

    this.travelConfigForm.get('branchMasterId')?.valueChanges.subscribe((branchId) => {
      if (branchId) {
        this.reloadBranchEmployees(Number(branchId));
        if (!this.isEditMode) this.applyFormListFilter();
      }
    });
  }

  private loadInitialCompanyBranch(): void {
    const companyId = this.authService.getCompanyId();
    if (!companyId) return;
    this.travelConfigForm.patchValue({ companyMasterId: companyId }, { emitEvent: false });
    this.apiService.get(`/api/TravelPayment/GetAllBranches/${companyId}`).subscribe((res: any) => {
      const data = res?.data ?? res?.Data ?? [];
      this.branches = (data as any[]).map((b) => ({
        id: Number(b.unitMasterId ?? b.id ?? b.branchId),
        displayName: `${b.name ?? b.branchName} (${b.code ?? b.branchCode})`,
      }));
      const branchId = this.authService.getBranchId();
      const selected = this.branches.find((b) => b.id === branchId) ?? this.branches[0];
      if (selected) {
        this.travelConfigForm.patchValue({ branchMasterId: selected.id });
      }
      this.loadUsedScopes();
    });
  }

  onBranchChanged(branchId?: number | null): void {
    const branch = Number(branchId ?? this.travelConfigForm.get('branchMasterId')?.value ?? 0);
    if (branch > 0) {
      this.clearBranchScopedApproverSelections();
      this.getEmployeeList(branch);
    } else {
      this.employees = [];
    }
    this.loadUsedScopes();
    if (!this.isEditMode) this.applyFormListFilter();
  }

  /** Only employee rows are branch-scoped (the employee list itself is fetched per-branch) — role/
   * department/designation selections are org-wide groupings via RBAC, so a branch change leaves
   * them untouched. */
  private clearBranchScopedApproverSelections(): void {
    this.selectorRows = this.selectorRows.filter((row) => row.selectorType !== 'employee');
    if (this.editingKey?.startsWith('employee:')) this.cancelApproverDetailsEdit();
  }

  private selectorKey(selectorType: SelectorType, selectorId: number): string {
    return `${selectorType}:${selectorId}`;
  }

  selectorTypeLabel(type: SelectorType): string {
    return this.selectorTypeOptions.find((o) => o.id === type)?.label ?? type;
  }

  setActiveSelectorType(type: SelectorType): void {
    this.activeSelectorType = type;
  }

  private loadSelectorGroups(): void {
    this.rbacService.getRoles().subscribe({
      next: (res: any) => {
        if (res?.isSuccess) this.roles = res.data ?? [];
      },
      error: (err) => console.error('Error loading roles for approver selector:', err),
    });
    this.rbacService.getDepartments().subscribe({
      next: (res: any) => {
        if (res?.isSuccess) {
          this.departments = (res.data ?? []).map((d: any) => ({
            id: Number(d.id ?? d.Id),
            name: d.name ?? d.Name,
          }));
        }
      },
      error: (err) => console.error('Error loading departments for approver selector:', err),
    });
    this.rbacService.getDesignations().subscribe({
      next: (res: any) => {
        if (res?.isSuccess) {
          this.designations = (res.data ?? []).map((d: any) => ({
            id: Number(d.id ?? d.Id),
            name: d.name ?? d.Name,
          }));
        }
      },
      error: (err) => console.error('Error loading designations for approver selector:', err),
    });
  }

  /** Items for the currently active selector-type's tag-box — one shared {id, label, code} shape
   * regardless of underlying source list, so the template doesn't need a template per type.
   *
   * Same bug family as activeSelectorValue below: this used to .map() a brand-new array of
   * brand-new object literals on every single read. Angular re-reads it on every change-detection
   * pass and rebinds dx-tag-box's [items] to that new reference even when the underlying
   * roles/departments/designations/employees list hasn't changed — DevExtreme treats a new
   * `items`/dataSource reference as "the data changed under you" and resets the open dropdown's
   * internal state, which can silently discard the click the user just made (reported 2026-10-10:
   * "unable to select any roles/department/designation" — the employee tag-box happened to dodge
   * this in practice since this screen's extra role/department/designation-only UI, like the
   * resolve preview below, triggers change detection far more often). Cached per selector type,
   * keyed on the *source array's own reference* (this.roles/this.departments/... are only ever
   * reassigned once per network response, never recreated per read) — so as long as the source
   * hasn't actually changed, the exact same output array/objects are returned every time. */
  private _activeSelectorItemsCache: Partial<
    Record<SelectorType, { source: any[]; items: { id: number; label: string; code?: string }[] }>
  > = {};

  get activeSelectorItems(): { id: number; label: string; code?: string }[] {
    const type = this.activeSelectorType;
    const source =
      type === 'role'
        ? this.roles
        : type === 'department'
          ? this.departments
          : type === 'designation'
            ? this.designations
            : this.employees;

    const cached = this._activeSelectorItemsCache[type];
    if (cached && cached.source === source) return cached.items;

    const items = this.computeActiveSelectorItems(type, source);
    this._activeSelectorItemsCache[type] = { source, items };
    return items;
  }

  private computeActiveSelectorItems(
    type: SelectorType,
    source: any[],
  ): { id: number; label: string; code?: string }[] {
    switch (type) {
      case 'role':
        return source.map((r: any) => ({
          id: Number(r.roleId ?? r.id),
          label: r.roleName ?? r.name ?? `Role #${r.roleId ?? r.id}`,
        }));
      case 'department':
      case 'designation':
        return source.map((d: any) => ({ id: d.id, label: d.name }));
      default:
        return source.map((e: any) => ({
          id: Number(e.employeeMasterID),
          label: `${e.firstName ?? ''} ${e.lastName ?? ''}`.trim(),
          code: e.code,
        }));
    }
  }

  // Bug (reported 2026-10-10): this getter used to build a brand-new array on every read. Angular
  // re-reads it on every change-detection pass and rebinds dx-tag-box's [value] to that new
  // reference even when the ids are identical; DevExtreme treats that as an external value change
  // and echoes onValueChanged, which rebuilt selectorRows and re-fetched ResolveSelector, which
  // changed selectorPreview/pendingRowLabels, triggering another CD pass — an infinite loop (435
  // calls/burst logged in production). Returning the SAME array instance when the underlying ids
  // haven't actually changed breaks that cycle at the source.
  private _activeSelectorValueCache: number[] = [];
  private _activeSelectorValueCacheKey = '';

  get activeSelectorValue(): number[] {
    const ids = this.selectorRows
      .filter((r) => r.selectorType === this.activeSelectorType)
      .map((r) => r.selectorId)
      .sort((a, b) => a - b);
    const key = `${this.activeSelectorType}:${ids.join(',')}`;
    if (key !== this._activeSelectorValueCacheKey) {
      this._activeSelectorValueCacheKey = key;
      this._activeSelectorValueCache = ids;
    }
    return this._activeSelectorValueCache;
  }

  /** Diffs the active type's tag-box selection against selectorRows, touching only rows of that
   * type — rows of every other type are left exactly as they were, so switching the toggle and
   * picking from a different list is additive, not a replacement. */
  onActiveSelectorChanged(ids: number[]): void {
    const type = this.activeSelectorType;
    const safeIds = (ids ?? []).map((x) => Number(x)).filter((x) => Number.isFinite(x) && x > 0);

    // Echo guard: DevExtreme can re-fire onValueChanged for a [value] rebind that didn't actually
    // change the selection (see activeSelectorValue's note above) — bail out before touching
    // selectorRows or firing a preview request when the incoming set is identical to what's
    // already stored, order ignored.
    const currentIds = this.selectorRows
      .filter((r) => r.selectorType === type)
      .map((r) => r.selectorId);
    const sortedIncoming = [...safeIds].sort((a, b) => a - b);
    const sortedCurrent = [...currentIds].sort((a, b) => a - b);
    const isSameSet =
      sortedIncoming.length === sortedCurrent.length &&
      sortedIncoming.every((id, i) => id === sortedCurrent[i]);
    if (isSameSet) return;

    const otherRows = this.selectorRows.filter((r) => r.selectorType !== type);
    const existingByType = new Map(
      this.selectorRows.filter((r) => r.selectorType === type).map((r) => [r.selectorId, r]),
    );
    const nextTypeRows: SelectorRow[] = safeIds.map(
      (id) => existingByType.get(id) ?? { selectorType: type, selectorId: id, stageOrder: 0 },
    );
    this.selectorRows = [...otherRows, ...nextTypeRows];

    if (
      this.editingKey &&
      !this.selectorRows.some((r) => this.selectorKey(r.selectorType, r.selectorId) === this.editingKey)
    ) {
      this.cancelApproverDetailsEdit();
    }

    if (type !== 'employee') this.refreshSelectorPreview(type);
  }

  /** "Select all" convenience (Frontend-Spec.md §1.1) — ticks every option currently in the active
   * type's list. UI convenience only: the backend stores exactly these rows, so a group created
   * later is NOT retroactively included — see the helper text next to this in the template. */
  selectAllActiveSelectorItems(): void {
    this.onActiveSelectorChanged(this.activeSelectorItems.map((i) => i.id));
  }

  clearActiveSelectorItems(): void {
    this.onActiveSelectorChanged([]);
  }

  /** Group selectors work for every form doc, Travel Management included (Approval-Admin-Override-
   * And-Group-Selectors-API-Contract.md §3, confirmed §4). Kept only to drive the Travel-specific
   * "fin" label hint below — Settlement/Advance-Payment visibility for a group row on a Travel
   * Advance Payment config requires its approvalType label to contain "fin" (§4's last bullet). */
  get isTravelManagementForm(): boolean {
    const formDocNo = Number(this.travelConfigForm?.get('formDocNo')?.value ?? 0);
    if (!formDocNo) return false;
    const doc = this.allFormOptions.find((f: any) => Number(f.id) === formDocNo);
    return !!doc?.moduleKey && /travel/i.test(`${doc.moduleKey}`);
  }

  get activeSelectorPreview() {
    return this.selectorPreview[this.activeSelectorType] ?? null;
  }

  get activeSelectorPreviewLoading(): boolean {
    return !!this.selectorPreviewLoading[this.activeSelectorType];
  }

  get activeSelectorPreviewExpanded(): boolean {
    return !!this.previewExpanded[this.activeSelectorType];
  }

  toggleActiveSelectorPreviewExpanded(): void {
    const type = this.activeSelectorType;
    this.previewExpanded[type] = !this.previewExpanded[type];
  }

  /** Calls ResolveSelector (§3 of the contract above) for every currently-selected id of one
   * selector type, so the admin sees real resolved employees/no-login counts before saving.
   * Dropped entirely (not fetched) for 'employee' rows — those are already named individuals.
   * Debounced (~300ms) and deduped by (type, sorted ids): onActiveSelectorChanged's echo guard
   * already stops most redundant calls, but "Select all"/rapid edits can still call this more than
   * once for the same effective selection before the previous request lands. */
  private refreshSelectorPreview(type: SelectorType): void {
    const ids = this.selectorRows
      .filter((r) => r.selectorType === type)
      .map((r) => r.selectorId)
      .sort((a, b) => a - b);

    clearTimeout(this.selectorPreviewDebounce[type]);

    if (!ids.length) {
      delete this.selectorPreview[type];
      delete this.selectorPreviewLoading[type];
      delete this.selectorPreviewInFlightKey[type];
      return;
    }

    const key = ids.join(',');
    this.selectorPreviewDebounce[type] = setTimeout(() => {
      if (this.selectorPreviewInFlightKey[type] === key) return;
      this.selectorPreviewInFlightKey[type] = key;
      this.fetchSelectorPreview(type, key);
    }, 300);
  }

  private fetchSelectorPreview(type: SelectorType, idsCsv: string): void {
    this.selectorPreviewLoading[type] = true;
    this.apiService
      .get(`/api/Approval/ResolveSelector?selectorType=${type}&selectorIds=${idsCsv}`)
      .subscribe({
        next: (res: any) => {
          this.selectorPreviewLoading[type] = false;
          if (this.selectorPreviewInFlightKey[type] === idsCsv) delete this.selectorPreviewInFlightKey[type];
          if (!res?.isSuccess || !res.data) return;

          const groups = (res.data.groups ?? []).map((g: any) => ({
            selectorId: Number(g.selectorId),
            groupName: g.groupName ?? `${this.selectorTypeLabel(type)} #${g.selectorId}`,
            employeeCount: Array.isArray(g.employees) ? g.employees.length : 0,
            withoutLoginCount: Number(g.withoutLoginCount ?? 0),
          }));
          const employees = (res.data.employees ?? []).map((e: any) => ({
            employeeId: Number(e.employeeId),
            employeeName: e.employeeName ?? `Emp#${e.employeeId}`,
            employeeCode: e.employeeCode ?? '',
            hasLoginUser: !!e.hasLoginUser,
          }));
          this.selectorPreview[type] = {
            groups,
            employees,
            withoutLoginCount: Number(res.data.withoutLoginCount ?? 0),
          };
          // Backfill real group names immediately instead of waiting on employees/roles/
          // departments/designations (which don't carry a resolved member count anyway).
          groups.forEach((g: any) => {
            this.pendingRowLabels[this.selectorKey(type, g.selectorId)] = g.groupName;
          });
        },
        error: (err) => {
          this.selectorPreviewLoading[type] = false;
          if (this.selectorPreviewInFlightKey[type] === idsCsv) delete this.selectorPreviewInFlightKey[type];
          const status = err?.status;
          if (status === 403) {
            // Frontend-Spec.md §1.2 — hide rather than error; this whole screen is admin
            // territory anyway, so a 403 here means the caller shouldn't be on this form at all.
            delete this.selectorPreview[type];
            return;
          }
          if (status === 404) {
            // A selected id no longer exists — drop it and refresh the picker's option list.
            this.selectorRows = this.selectorRows.filter((r) => r.selectorType !== type);
            delete this.selectorPreview[type];
            this.toaster.warning(
              `One or more selected ${this.selectorTypeLabel(type).toLowerCase()}s no longer exist and were removed.`,
            );
            return;
          }
          console.error(`Error resolving ${type} selector preview:`, err);
        },
      });
  }

  private scopeKey(branchMasterId: number, formDocNo: number): string {
    return `${branchMasterId}:${formDocNo}`;
  }

  private reloadBranchEmployees(branchId: number): void {
    this.getEmployeeList(branchId);
  }

  hide(): void {
    this.showPopup = !this.showPopup;
  }

  optionsClick(): void {
    this.showPopup = !this.showPopup;
  }

  setMode(mode: ApprovalMode): void {
    this.travelConfigForm.patchValue({ approvalMode: mode });
  }

  get isDefaultMode(): boolean {
    return this.travelConfigForm?.value?.approvalMode === this.APPROVAL_MODES.DEFAULT_CHAIN;
  }

  get isAnyOneMode(): boolean {
    return this.travelConfigForm?.value?.approvalMode === this.APPROVAL_MODES.ANY_ONE;
  }

  get isSelectedEmployeeMode(): boolean {
    return (
      this.travelConfigForm?.value?.approvalMode === this.APPROVAL_MODES.SELECTED_EMPLOYEE_OVERRIDE
    );
  }

  get isEmployeeOverrideMode(): boolean {
    return this.isAnyOneMode || this.isSelectedEmployeeMode;
  }

  get isFirstDecisionWinsMode(): boolean {
    return this.travelConfigForm?.value?.approvalMode === this.APPROVAL_MODES.FIRST_DECISION_WINS;
  }

  /** Display-ready rows — resolves each row's label/code from the matching source list
   * (employees/roles/departments/designations), falling back to a cached backend-provided label
   * (pendingRowLabels) or a generic "#id" placeholder while that list is still loading. */
  get displayApproverRows(): SelectedApproverRow[] {
    return this.selectorRows.map((row) => {
      const key = this.selectorKey(row.selectorType, row.selectorId);
      let label = this.pendingRowLabels[key] ?? '';
      let code = '';

      if (row.selectorType === 'employee') {
        const emp = this.employees.find((e) => Number(e.employeeMasterID) === row.selectorId);
        if (emp) {
          label = `${emp.firstName ?? ''} ${emp.lastName ?? ''}`.trim() || label;
          code = `${emp.code ?? ''}`;
        }
      } else {
        const source =
          row.selectorType === 'role'
            ? this.roles
            : row.selectorType === 'department'
              ? this.departments
              : this.designations;
        const found = source.find(
          (g: any) => Number(g.roleId ?? g.id) === row.selectorId,
        );
        if (found) label = found.roleName ?? found.name ?? label;
      }

      if (!label) label = `${this.selectorTypeLabel(row.selectorType)} #${row.selectorId}`;

      return {
        ...row,
        key,
        employeeId: row.selectorType === 'employee' ? row.selectorId : 0,
        label,
        code,
      };
    });
  }

  private findSelectorRowIndex(key: string): number {
    return this.selectorRows.findIndex((r) => this.selectorKey(r.selectorType, r.selectorId) === key);
  }

  hasApproverDetails(key: string): boolean {
    const idx = this.findSelectorRowIndex(key);
    if (idx < 0) return false;
    const row = this.selectorRows[idx];
    return !!(row.designation || row.approvalType);
  }

  openApproverDetailsEditor(key: string): void {
    const idx = this.findSelectorRowIndex(key);
    const row = idx >= 0 ? this.selectorRows[idx] : null;
    this.editingKey = key;
    this.editorDraft = {
      designation: row?.designation ?? '',
      approvalType: row?.approvalType ?? '',
    };
  }

  cancelApproverDetailsEdit(): void {
    this.editingKey = null;
    this.editorDraft = { designation: '', approvalType: '' };
  }

  saveApproverDetails(key: string): void {
    const idx = this.findSelectorRowIndex(key);
    if (idx < 0) return;
    // Optional fields: we persist as undefined when blank.
    const designation = `${this.editorDraft.designation ?? ''}`.trim();
    const approvalType = `${this.editorDraft.approvalType ?? ''}`.trim();
    this.selectorRows[idx] = {
      ...this.selectorRows[idx],
      designation: designation || undefined,
      approvalType: approvalType || undefined,
    };
    this.cancelApproverDetailsEdit();
  }

  clearApproverDetails(key: string): void {
    const idx = this.findSelectorRowIndex(key);
    if (idx < 0) return;
    // Stage assignment is independent of the optional designation/approval-type details —
    // "Clear" only wipes those two, not which stage this approver races/chains in.
    this.selectorRows[idx] = {
      ...this.selectorRows[idx],
      designation: undefined,
      approvalType: undefined,
    };
    if (this.editingKey === key) this.cancelApproverDetailsEdit();
  }

  /** Only meaningful for default_chain — see SelectorRow.stageOrder. */
  setApproverStage(key: string, stage: number | string | null): void {
    const idx = this.findSelectorRowIndex(key);
    if (idx < 0) return;
    const parsed = Math.trunc(Number(stage));
    const safeStage = Number.isFinite(parsed) && parsed >= 0 ? parsed : 0;
    this.selectorRows[idx] = { ...this.selectorRows[idx], stageOrder: safeStage };
  }

  /** Default-chain-only grouping preview: approvers sharing a stageOrder run together, ordered
   * lowest stage first. Per the contract above, a stage containing any role/department/designation
   * row becomes AnyOne (any one resolved member, or any named employee in that stage, can approve);
   * a stage of only named employees stays Unanimous, same as before. */
  get stageGroupsPreview(): { stageOrder: number; names: string[]; isAnyOne: boolean }[] {
    const byStage = new Map<number, { names: string[]; isAnyOne: boolean }>();
    this.displayApproverRows.forEach((row) => {
      const entry = byStage.get(row.stageOrder) ?? { names: [], isAnyOne: false };
      entry.names.push(row.label);
      if (row.selectorType !== 'employee') entry.isAnyOne = true;
      byStage.set(row.stageOrder, entry);
    });
    return Array.from(byStage.entries())
      .sort((a, b) => a[0] - b[0])
      .map(([stageOrder, entry]) => ({ stageOrder, names: entry.names, isAnyOne: entry.isAnyOne }));
  }

  get currentModeInstruction(): string {
    if (this.isAnyOneMode) {
      return 'Any one selected employee can approve; after first approval the request becomes approved. You may also keep Reporting Manager as an extra required gate.';
    }
    if (this.isSelectedEmployeeMode) {
      return 'Only selected employees can approve. This mode overrides the standard hierarchy and bypasses the Reporting Manager.';
    }
    if (this.isFirstDecisionWinsMode) {
      return 'Reporting Manager (if included) and every selected employee can independently approve or reject — whoever decides first, in either direction, wins. Not sequential, no unanimous requirement.';
    }
    return 'Reporting Manager (if included) approves first. Remaining approvers run in Stage order below — everyone sharing a stage must approve (unanimous) before the next stage opens.';
  }

  loadUsedScopes(): void {
    const companyId = Number(this.travelConfigForm.get('companyMasterId')?.value ?? 0);
    const branchId = Number(this.travelConfigForm.get('branchMasterId')?.value ?? 0);
    const query =
      companyId > 0
        ? `?companyMasterId=${companyId}${branchId > 0 ? `&branchMasterId=${branchId}` : ''}`
        : '';
    this.apiService.get(`/api/TravelConfig/GetAll${query}`).subscribe({
      next: (res: any) => {
        const rows = res?.data ?? [];
        this.usedScopeKeys = new Set(
          rows
            .map((r: { branchMasterId?: number; formDocNo?: number }) =>
              this.scopeKey(Number(r.branchMasterId), Number(r.formDocNo)),
            )
            .filter((k: string) => k && !k.startsWith('0:')),
        );
        if (!this.isEditMode) this.applyFormListFilter();
      },
    });
  }

  private applyFormListFilter(): void {
    if (!this.allFormOptions?.length) return;

    // Edit mode: derive the Module filter from whatever form doc was already loaded, regardless
    // of whether getFormList() or getById() resolved first.
    if (this.isEditMode && !this.selectedModuleKey) {
      const formDocNo = Number(this.travelConfigForm.get('formDocNo')?.value ?? 0);
      const currentDoc = this.allFormOptions.find((f: any) => Number(f.id) === formDocNo);
      if (currentDoc?.moduleKey) this.selectedModuleKey = currentDoc.moduleKey;
    }

    const branchId = Number(this.travelConfigForm.get('branchMasterId')?.value ?? 0);
    this.formList = this.allFormOptions.filter(
      (f) =>
        !this.usedScopeKeys.has(this.scopeKey(branchId, Number(f.id))) &&
        (!this.selectedModuleKey || f.moduleKey === this.selectedModuleKey),
    );
  }

  onModuleFilterChanged(moduleKey: string | null): void {
    this.selectedModuleKey = moduleKey || null;
    // Changing module invalidates whatever form doc was picked from the other module.
    if (!this.isEditMode) {
      this.travelConfigForm.patchValue({ formDocNo: null }, { emitEvent: false });
      this.applyFormListFilter();
    }
  }

  isFormScopeAlreadyUsed(formDocNo: number | null | undefined): boolean {
    if (!formDocNo || this.isEditMode) return false;
    const branchId = Number(this.travelConfigForm.get('branchMasterId')?.value ?? 0);
    return this.usedScopeKeys.has(this.scopeKey(branchId, Number(formDocNo)));
  }

  validateBeforeSave(): string | null {
    const v = this.travelConfigForm.getRawValue();

    if (!v.companyMasterId || !v.branchMasterId) return 'Please select company and branch.';
    if (!v.formDocNo) return 'Please select a form type.';

    if (v.approvalMode === this.APPROVAL_MODES.DEFAULT_CHAIN) {
      if (!v.isReportingMgrRequired) return 'Reporting Manager approval is required.';
    } else if (v.approvalMode === this.APPROVAL_MODES.FIRST_DECISION_WINS) {
      // Matches the backend's own validation rule (§7.1): at least one of {Reporting Manager
      // included, a non-empty selectedApprovers} is required, or Insert/Update refuses with 400.
      if (!v.isReportingMgrRequired && !this.selectorRows.length) {
        return 'Select at least one approver, or include the Reporting Manager, for First Decision Wins mode.';
      }
    } else {
      // any_one + selected_employee_override
      if (!this.selectorRows.length) return 'Please select at least one approver.';
    }

    if (!this.isEditMode && this.isFormScopeAlreadyUsed(v.formDocNo)) {
      return 'A configuration already exists for this branch and form. Edit the existing record from the list.';
    }

    if (this.isEditMode && this.lockedScope) {
      if (
        Number(v.companyMasterId) !== this.lockedScope.companyMasterId ||
        Number(v.branchMasterId) !== this.lockedScope.branchMasterId ||
        Number(v.formDocNo) !== this.lockedScope.formDocNo
      ) {
        return 'Branch and form type cannot be changed after creation. Create a new configuration instead.';
      }
    }

    return null;
  }

  /**
   * Everyone offered as an approver here - a named approver or the fallback approver - has to sign in to
   * approve, so the list is the employees bound to an active login in the user master (the same source the
   * RBAC "assign roles" screen uses), not the whole employee master. The company comes from the session.
   */
  getEmployeeList(branchId?: number): void {
    const branch = branchId ?? Number(this.travelConfigForm.get('branchMasterId')?.value ?? 0);

    this.employeesLoaded = false;
    this.employees = [];
    if (branch <= 0) return;

    this.apiService.get(`/api/ApproverCandidates?branch=${branch}`).subscribe({
      next: (res: any) => {
        this.employees = this.normalizeLookupEmployees(res);
        this.employeesLoaded = true;
      },
      error: (err) => {
        console.error(err);
        this.employees = [];
      },
    });
  }

  /** True once the list of employees with a login has loaded for the current branch. */
  private employeesLoaded = false;

  /**
   * Approvers already saved on this config who are not in the list above: a named employee or the fallback
   * approver whose login has since been removed (or who never had one). They can never be asked to approve,
   * so the admin is told to replace them instead of it going unnoticed.
   */
  get approversWithoutLogin(): string[] {
    if (!this.employeesLoaded) return [];

    const withLogin = new Set(this.employees.map((e) => Number(e.employeeMasterID)));
    const names = this.displayApproverRows
      .filter((row) => row.selectorType === 'employee' && !withLogin.has(row.selectorId))
      .map((row) => row.label);

    const fallbackId = Number(this.travelConfigForm?.get('fallbackApproverId')?.value ?? 0);
    if (fallbackId && this.travelConfigForm?.value?.isReportingMgrRequired && !withLogin.has(fallbackId)) {
      names.push(`${this.fallbackApproverLabel} (fallback approver)`);
    }
    return names;
  }

  employeeDisplayExpr = (item: any) => {
    if (!item) return '';
    return `${item.firstName ?? ''} ${item.lastName ?? ''}`.trim();
  };

  get selectedFormLabel(): string {
    const id = this.travelConfigForm?.value?.formDocNo;
    const found = this.formList?.find((f) => Number(f.id) === Number(id));
    return found?.formName ?? '—';
  }

  get reportingManagerLabel(): string {
    return this.travelConfigForm?.value?.isReportingMgrRequired ? 'Included' : 'Not included';
  }

  get approverCountLabel(): string {
    const n = this.selectorRows.length;
    return `${n} approver${n === 1 ? '' : 's'}`;
  }

  get fallbackApproverLabel(): string {
    const id = Number(this.travelConfigForm?.get('fallbackApproverId')?.value ?? 0);
    if (!id) return 'Not set';
    const emp = this.employees.find((e) => Number(e.employeeMasterID) === id);
    const name = emp ? `${emp.firstName ?? ''} ${emp.lastName ?? ''}`.trim() : '';
    return name || `Employee #${id}`;
  }

  get approvalModeLabel(): string {
    const mode: ApprovalMode = this.travelConfigForm?.value?.approvalMode;
    if (mode === this.APPROVAL_MODES.ANY_ONE) return 'Any One';
    if (mode === this.APPROVAL_MODES.SELECTED_EMPLOYEE_OVERRIDE) return 'Select Employee';
    if (mode === this.APPROVAL_MODES.FIRST_DECISION_WINS) return 'First Decision Wins';
    return 'Default';
  }

  getFormList(): void {
    // Cross-module catalogue (Approval-Engine-API-Contract.md §3) — replaces the travel-only
    // /api/TravelConfig/GetAllFormDoc. No moduleKey query param here: we want every module's
    // docs so the Module filter below has something to filter.
    this.apiService.get('/api/FormDocMaster/GetAll').subscribe({
      next: (res: any) => {
        if (!res.isSuccess) return;
        this.allFormOptions = res.data ?? [];
        this.moduleOptions = Array.from(
          new Set<string>(this.allFormOptions.map((f: any) => f.moduleKey).filter(Boolean)),
        )
          .sort()
          .map((key) => ({ key }));
        this.applyFormListFilter();
      },
    });
  }

  getById(id: number): void {
    this.apiService.get(`/api/TravelConfig/${id}`).subscribe({
      next: (res: any) => {
        if (!res.isSuccess) return;
        const data = res.data;

        const mode = this.normalizeApprovalMode(data.approvalMode);
        this.hydrateSelectedApprovers(this.withLegacyDefaultChainFallback(mode, data));

        this.travelConfigForm.patchValue({
          id: data.id ?? id,
          companyMasterId: Number(data.companyMasterId ?? data.CompanyMasterId ?? 0) || null,
          branchMasterId: Number(data.branchMasterId ?? data.BranchMasterId ?? 0) || null,
          formDocNo: data.formDocNo,
          approvalMode: mode,
          isReportingMgrRequired: data.isReportingMgrRequired ?? true,
          fallbackApproverId:
            Number(data.fallbackApproverId ?? data.FallbackApproverId ?? 0) || null,
        });
        this.applyReportingManagerControlState(mode);
        const branchId = Number(data.branchMasterId ?? data.BranchMasterId ?? 0);
        if (branchId > 0) this.reloadBranchEmployees(branchId);
        this.lockScopeFieldsAfterLoad();
      },
    });
  }

  /** Pre-§7.2 configs only ever set these two fixed-role fields — the DTO still accepts them but
   * the engine no longer reads them for default_chain (Approval-Engine-API-Contract.md §7.2), so
   * synthesize equivalent selectedApprovers rows here purely so this screen keeps showing them,
   * and so the next Save carries them forward correctly under the new model instead of silently
   * losing them. Only kicks in when the backend hasn't already returned real selectedApprovers
   * rows for this config. */
  private withLegacyDefaultChainFallback(mode: ApprovalMode, data: any): any[] {
    const apiRows: any[] = Array.isArray(data?.selectedApprovers) ? data.selectedApprovers : [];
    if (mode !== this.APPROVAL_MODES.DEFAULT_CHAIN || apiRows.length) return apiRows;

    const synthesized: any[] = [];
    const financeId = Number(data?.financeApproverId ?? data?.FinanceApproverId ?? 0);
    if (data?.isFinanceApproverRequired && financeId > 0) {
      synthesized.push({ employeeId: financeId, approvalType: 'Finance', stageOrder: 0 });
    }
    const hrId = Number(data?.hrApproverId ?? data?.HrApproverId ?? 0);
    if (data?.isHrRequired && hrId > 0) {
      synthesized.push({ employeeId: hrId, approvalType: 'HR', stageOrder: 0 });
    }
    return synthesized;
  }

  /** Edit mode: branch + form are fixed after create to avoid duplicate/conflicting configs. */
  private lockScopeFieldsAfterLoad(): void {
    if (!this.isEditMode) return;

    // Derives the Module filter from the now-loaded formDocNo, regardless of whether
    // getFormList() resolved before or after this getById() callback.
    this.applyFormListFilter();

    const companyId = Number(this.travelConfigForm.get('companyMasterId')?.value ?? 0);
    const branchId = Number(this.travelConfigForm.get('branchMasterId')?.value ?? 0);
    const formDocNo = Number(this.travelConfigForm.get('formDocNo')?.value ?? 0);
    if (companyId > 0 && branchId > 0 && formDocNo > 0) {
      this.lockedScope = { companyMasterId: companyId, branchMasterId: branchId, formDocNo };
    }

    this.travelConfigForm.get('branchMasterId')?.disable({ emitEvent: false });
    this.travelConfigForm.get('formDocNo')?.disable({ emitEvent: false });

    const currentForm = this.allFormOptions.find((f) => Number(f.id) === formDocNo);
    if (currentForm && !this.formList.some((f) => Number(f.id) === formDocNo)) {
      this.formList = [...this.formList, currentForm];
    }
  }

  get lockedBranchLabel(): string {
    const branchId = this.lockedScope?.branchMasterId;
    if (!branchId) return '—';
    return this.branches.find((b) => b.id === branchId)?.displayName ?? `Branch #${branchId}`;
  }

  save(): void {
    this.formSubmitted = true;
    this.travelConfigForm.markAllAsTouched();

    const clientError = this.validateBeforeSave();
    if (clientError) {
      this.toaster.warning(clientError);
      return;
    }

    if (this.travelConfigForm.invalid) {
      this.toaster.warning('Please fill all required fields.');
      return;
    }

    const apiPayload = this.buildApiPayload();

    if (this.isEditMode) {
      this.apiService.put('/api/TravelConfig/Update', apiPayload).subscribe({
        next: (res: any) => this.handleSaveResponse(res, 'update'),
        error: (err) => this.handleSaveError(err, 'update'),
      });
    } else {
      this.apiService.post('/api/TravelConfig/Insert', apiPayload).subscribe({
        next: (res: any) => this.handleSaveResponse(res, 'insert'),
        error: (err) => this.handleSaveError(err, 'insert'),
      });
    }
  }

  private handleSaveResponse(res: any, mode: 'insert' | 'update'): void {
    if (res?.isSuccess) {
      this.toaster.success(
        res.message ?? (mode === 'insert' ? 'Saved successfully' : 'Updated successfully'),
      );
      this.router.navigate(['/admin/hr-config']);
      return;
    }
    this.toaster.error(
      res?.message ??
        (mode === 'insert'
          ? 'Could not save configuration.'
          : 'Could not update configuration.'),
    );
  }

  private handleSaveError(err: any, mode: 'insert' | 'update'): void {
    const msg =
      err?.error?.message ??
      (mode === 'insert' ? 'Could not save configuration.' : 'Could not update configuration.');
    this.toaster.error(msg);
  }

  /**
   * API contract mapper (Approval-Engine-API-Contract.md §7.2): every mode now sends the same
   * generic selectedApprovers array; the old fixed-role Finance/HR fields are retired here (the
   * DTO still accepts them, but the engine no longer reads them for default_chain, so there's
   * nothing to gain by still sending them).
   */
  private buildApiPayload(): any {
    const formValue = this.travelConfigForm.getRawValue();
    return {
      id: formValue.id,
      companyMasterId: Number(formValue.companyMasterId),
      branchMasterId: Number(formValue.branchMasterId),
      formDocNo: formValue.formDocNo,
      approvalMode: this.normalizeApprovalMode(formValue.approvalMode),
      isReportingMgrRequired: !!formValue.isReportingMgrRequired,
      // Null, not 0, when unset — 0 isn't a real employee id and would read as "resolved" instead
      // of "not configured" on the backend side.
      fallbackApproverId: Number(formValue.fallbackApproverId) || null,
      selectedApprovers: this.buildSelectedApproversForPayload(),
    };
  }

  private normalizeApprovalMode(rawMode: unknown): ApprovalMode {
    const value = `${rawMode ?? ''}`.trim().toLowerCase() as ApprovalMode;
    if (value === this.APPROVAL_MODES.ANY_ONE) return this.APPROVAL_MODES.ANY_ONE;
    if (value === this.APPROVAL_MODES.SELECTED_EMPLOYEE_OVERRIDE) {
      return this.APPROVAL_MODES.SELECTED_EMPLOYEE_OVERRIDE;
    }
    if (value === this.APPROVAL_MODES.FIRST_DECISION_WINS) return this.APPROVAL_MODES.FIRST_DECISION_WINS;
    return this.APPROVAL_MODES.DEFAULT_CHAIN;
  }

  private applyReportingManagerControlState(mode: ApprovalMode): void {
    const rmCtrl = this.travelConfigForm.get('isReportingMgrRequired');
    if (!rmCtrl) return;

    if (mode === this.APPROVAL_MODES.SELECTED_EMPLOYEE_OVERRIDE) {
      // "In specific Employee, we do not give reporting manager check!"
      rmCtrl.setValue(false, { emitEvent: false });
      rmCtrl.disable({ emitEvent: false });
      return;
    }

    // Default Chain, Any One and First Decision Wins all allow toggling.
    rmCtrl.enable({ emitEvent: false });
  }

  /** Same generic row shape for every mode now (Approval-Engine-API-Contract.md §7.2), extended
   * with selectorType/selectorId (Approval-Admin-Override-And-Group-Selectors-API-Contract.md §3)
   * — stageOrder only means something for default_chain, every other mode ignores it server-side.
   * Group rows (non-'employee') work for every form doc, Travel Management included — but on a
   * Travel Advance Payment config, only a row whose approvalType label contains "fin" also grants
   * Settlement/Payment-screen visibility (§4's last bullet) — see isTravelManagementForm's helper
   * text in the template. */
  private buildSelectedApproversForPayload(): any[] {
    return this.selectorRows
      .filter((row) => row.selectorId > 0)
      .map((row) => ({
        selectorType: row.selectorType,
        selectorId: row.selectorId,
        employeeId: row.selectorType === 'employee' ? row.selectorId : undefined,
        designation: row.designation || undefined,
        approvalType: row.approvalType || undefined,
        stageOrder: row.stageOrder ?? 0,
      }));
  }

  private hydrateSelectedApprovers(apiRows: any[]): void {
    this.pendingRowLabels = {};

    this.selectorRows = (apiRows ?? [])
      .map((r: any): SelectorRow | null => {
        const selectorType: SelectorType = (r.selectorType ?? r.SelectorType ?? 'employee') as SelectorType;
        const selectorId = Number(
          selectorType === 'employee' ? (r.employeeId ?? r.EmployeeId) : (r.selectorId ?? r.SelectorId),
        );
        if (!Number.isFinite(selectorId) || selectorId <= 0) return null;

        // selectorName is the backend's resolved label for group rows (Approval-Admin-Override-
        // And-Group-Selectors-API-Contract.md §3's GetAll/GetById reads); employeeName/groupName
        // covered the pre-contract-finalization shape and stay as a fallback.
        const cachedLabel = `${
          r.selectorName ?? r.SelectorName ?? r.employeeName ?? r.EmployeeName ?? r.groupName ?? r.GroupName ?? ''
        }`.trim();
        if (cachedLabel) this.pendingRowLabels[this.selectorKey(selectorType, selectorId)] = cachedLabel;

        return {
          selectorType,
          selectorId,
          designation: `${r.designation ?? r.Designation ?? ''}`.trim() || undefined,
          approvalType: `${r.approvalType ?? r.ApprovalType ?? ''}`.trim() || undefined,
          stageOrder: Number(r.stageOrder ?? r.StageOrder ?? 0) || 0,
        };
      })
      .filter((r): r is SelectorRow => r !== null);

    const typesToPreview = new Set(
      this.selectorRows.map((r) => r.selectorType).filter((t) => t !== 'employee'),
    );
    typesToPreview.forEach((t) => this.refreshSelectorPreview(t));
  }

  private normalizeLookupEmployees(res: any): any[] {
    const source = res?.users ?? res?.data ?? [];
    if (!Array.isArray(source)) return [];
    return source.map((e: any) => ({
      employeeMasterID: Number(e.employeeMasterId ?? e.EmployeeMasterId ?? e.employeeMasterID ?? e.EmployeeMasterID ?? e.id ?? e.Id ?? 0),
      firstName: e.firstName ?? e.FirstName ?? '',
      lastName: e.lastName ?? e.LastName ?? '',
      code: e.code ?? e.Code ?? '',
    }));
  }

  onCancel(): void {
    this.router.navigate(['/admin/hr-config']);
  }
}

