}
import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule, Routes } from '@angular/router';
import { List } from './list/list';
import { Form } from './form/form';

const routes: Routes = [
  { path: '', component: List },
  { path: 'editform/:id', component: Form },
  { path: 'editform', component: Form },
];

@NgModule({
  declarations: [],
  imports: [
    CommonModule,
    RouterModule.forChild(routes)
  ]
})
export class HrConfigModule { }
import { Component, Input } from '@angular/core';
import { Router, ActivatedRoute } from '@angular/router';
import { ApiService } from '../../../../services/api.service';
import { AuthService } from '../../../../services/auth.service';
import { ChipNavigationService } from '../../../../services/ChipNavigation.service';
import { DxButtonModule, DxDataGridModule, DxPopupModule, DxSelectBoxModule } from 'devextreme-angular';
import { isAdminRole } from '../hr-config-role.util';
import { CommonGridComponent } from '../../../../layout/common-grid/common-grid.component';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-list',
  imports: [CommonModule, DxButtonModule, DxDataGridModule, DxPopupModule, DxSelectBoxModule, CommonGridComponent],
  templateUrl: './list.html',
  styleUrl: './list.scss',
})
export class List {
  constructor(
    private router: Router,
    private authService: AuthService,
    private route: ActivatedRoute,
    private chipService: ChipNavigationService,
    private apiservice: ApiService,
  ) {
    this.chipService.addTab({
      title: 'HR Config',
      route: '/admin/hr-config',
    });

    this.authService.ScreenName = 'HR Config';
    this.isAdmin = isAdminRole(localStorage.getItem('role') ?? '');
    this.companyId = this.authService.getCompanyId();
  }

  data: any[] = [];
  rawData: any[] = [];
  columns: any[] = [];
  branches: { id: number; displayName: string }[] = [];
  filterBranchId: number | null = null;
  isAdmin = false;
  companyId = 0;

  /** formDocNo -> moduleKey, from the shared FormDocMaster catalogue (§3/§7 of the API contract)
   * — /api/TravelConfig/GetAll itself has no moduleKey column, so it's joined in client-side. */
  formDocModuleMap: Record<number, string> = {};
  /** Wrapped as {key} objects with an explicit displayExpr/valueExpr, not a raw primitive-string
   * array — see the identical fix in hr-config/form/form.ts for why (a "flatMap is not a
   * function" crash in dx-select-box's internal item-resolution on a bare primitive array). */
  moduleOptions: { key: string }[] = [];
  filterModuleKey: string | null = null;

  get gridSubtitle(): string {
    const n = this.data?.length ?? 0;
    const label = n === 1 ? 'configuration' : 'configurations';
    if (this.filterBranchId && this.filterBranchId > 0) {
      const branch = this.branches.find((b) => b.id === this.filterBranchId);
      const branchName = branch?.displayName ?? `Branch #${this.filterBranchId}`;
      return `${n} ${label} · ${branchName}`;
    }
    return `${n} ${label} · All branches`;
  }

  refresh(): void {
    this.GetAllHrConfigs();
  }

  ngOnInit(): void {
    this.initializeColumns();
    this.loadFormDocModuleMap();
    this.loadBranchesThenConfigs();
  }

  loadFormDocModuleMap(): void {
    this.apiservice.get('/api/FormDocMaster/GetAll').subscribe({
      next: (res: any) => {
        const rows = res?.data ?? [];
        this.formDocModuleMap = {};
        rows.forEach((r: any) => {
          this.formDocModuleMap[Number(r.id)] = r.moduleKey;
        });
        this.moduleOptions = Array.from(
          new Set<string>(rows.map((r: any) => r.moduleKey).filter(Boolean)),
        )
          .sort()
          .map((key) => ({ key }));
        this.rebuildGridData();
      },
      error: (err) => console.error('Error fetching form doc catalogue', err),
    });
  }

  onModuleFilterChanged(moduleKey: string | null): void {
    this.filterModuleKey = moduleKey || null;
    this.rebuildGridData();
  }

  loadBranchesThenConfigs(): void {
    if (!this.companyId) {
      this.GetAllHrConfigs();
      return;
    }
    this.apiservice.get(`/api/TravelPayment/GetAllBranches/${this.companyId}`).subscribe((res: any) => {
      const data = res?.data ?? res?.Data ?? [];
      this.branches = (data as any[]).map((b) => ({
        id: Number(b.unitMasterId ?? b.id),
        displayName: `${b.name ?? b.branchName} (${b.code ?? b.branchCode})`,
      }));
      if (!this.isAdmin) {
        this.filterBranchId = this.authService.getBranchId() || this.branches[0]?.id || null;
      }
      this.GetAllHrConfigs();
    });
  }

  onBranchFilterChanged(branchId: number | null): void {
    this.filterBranchId = branchId;
    this.GetAllHrConfigs();
  }

  // ✅ COLUMN CONFIG
  // Finance/HR are no longer fixed, dedicated roles (Approval-Engine-API-Contract.md §7.2 — every
  // mode, including default_chain, now uses the same free-form approverSummary below), so there
  // are no more mode-dependent extra columns to toggle.
  initializeColumns(): void {
    const baseColumns = [
      {
        dataField: 'moduleKey',
        caption: 'Module',
      },
      {
        dataField: 'branchName',
        caption: 'Branch',
      },
      {
        dataField: 'formName',
        caption: 'Form Doc Type',
      },
      {
        dataField: 'approvalMode',
        caption: 'Approval Mode',
        cellTemplate: (container: any, options: any) => {
          const mode = this.normalizeApprovalMode(options?.data?.approvalMode);
          const badge = document.createElement('span');
          badge.className =
            'badge rounded-pill px-3 py-2 fw-semibold ' +
            (mode === 'default_chain'
              ? 'bg-light text-dark border'
              : mode === 'any_one'
                ? 'bg-info text-dark'
                : mode === 'first_decision_wins'
                  ? 'bg-primary text-white'
                  : 'bg-warning text-dark');
          badge.innerText = this.modeLabel(mode);
          container.appendChild(badge);
        },
      },
      {
        dataField: 'approverSummary',
        caption: 'Approvers Summary',
      },
    ];

    this.columns = baseColumns;
  }

  // ✅ GET DATA
  GetAllHrConfigs() {
    const params: string[] = [];
    if (this.companyId > 0) params.push(`companyMasterId=${this.companyId}`);
    if (this.filterBranchId && this.filterBranchId > 0) params.push(`branchMasterId=${this.filterBranchId}`);
    const query = params.length ? `?${params.join('&')}` : '';
    this.apiservice.get(`/api/TravelConfig/GetAll${query}`).subscribe({
      next: (res) => {
        this.rawData = res?.data || [];
        this.rebuildGridData();
      },
      error: (err) => {
        console.error('Error fetching HR Configs', err);
      },
    });
  }

  private rebuildGridData(): void {
    const mapped = this.rawData.map((row: any) => this.mapRowForGrid(row));
    this.data = this.filterModuleKey
      ? mapped.filter((row) => row.moduleKey === this.filterModuleKey)
      : mapped;
  }

  private normalizeApprovalMode(
    raw: unknown,
  ): 'default_chain' | 'any_one' | 'selected_employee_override' | 'first_decision_wins' {
    const v = `${raw ?? ''}`.trim().toLowerCase();
    if (v === 'any_one') return 'any_one';
    if (v === 'selected_employee_override') return 'selected_employee_override';
    // Exact string, verbatim from backend — Approval-Engine-API-Contract.md §7.1.
    if (v === 'first_decision_wins') return 'first_decision_wins';
    return 'default_chain';
  }

  private modeLabel(
    mode: 'default_chain' | 'any_one' | 'selected_employee_override' | 'first_decision_wins',
  ): string {
    if (mode === 'any_one') return 'Any One';
    if (mode === 'selected_employee_override') return 'Select Employee';
    if (mode === 'first_decision_wins') return 'First Decision Wins';
    return 'Default Chain';
  }

  /**
   * Creates a user-readable approver summary for list grid.
   * Supports both:
   * 1) New API with selectedApprovers (+ stageOrder, Approval-Engine-API-Contract.md §7.2) in GetAll.
   * 2) Fallback fields (financeApproverName/hrAdminName) for a default_chain row saved before §7.2,
   *    before it's been reopened and resaved under the new model.
   */
  private buildApproverSummary(row: any): string {
    const mode = this.normalizeApprovalMode(row?.approvalMode);
    const selectedApprovers = Array.isArray(row?.selectedApprovers) ? row.selectedApprovers : [];
    // Group rows (Approval-Admin-Override-And-Group-Selectors-API-Contract.md §3) have
    // employeeId/employeeName null — render via selectorName instead, never crash on the null.
    const label = (a: any) => {
      const selectorType = `${a?.selectorType ?? a?.SelectorType ?? 'employee'}`.toLowerCase();
      const type = `${a?.approvalType ?? ''}`.trim();
      if (selectorType !== 'employee') {
        const groupName =
          `${a?.selectorName ?? a?.SelectorName ?? ''}`.trim() ||
          `${selectorType} #${a?.selectorId ?? a?.SelectorId ?? ''}`;
        const typeLabel = selectorType.charAt(0).toUpperCase() + selectorType.slice(1);
        const base = `${groupName} (${typeLabel})`;
        return type ? `${base} — ${type}` : base;
      }
      const name = `${a?.employeeName ?? ''}`.trim() || `Emp#${a?.employeeId ?? ''}`;
      return type ? `${name} (${type})` : name;
    };
    // Reporting Manager is resolved dynamically per-request and can come back null (employee has
    // no ReportingPersonID) — see docs/specs/Fallback-Reporting-Manager-Backend-Spec.md. Surface
    // whether this config has a safety net configured for that case.
    const reportingManagerLabel = (): string => {
      const fallbackId = Number(row?.fallbackApproverId ?? row?.FallbackApproverId ?? 0);
      if (!fallbackId) return 'Reporting Manager';
      const fallbackName = `${row?.fallbackApproverName ?? row?.FallbackApproverName ?? ''}`.trim();
      return `Reporting Manager (fallback: ${fallbackName || `Emp#${fallbackId}`})`;
    };

    if (mode === 'first_decision_wins') {
      const labels = selectedApprovers.map(label);
      if (row?.isReportingMgrRequired) labels.unshift(reportingManagerLabel());
      return labels.length ? `Race to decide: ${labels.join(', ')}` : 'No approvers configured';
    }

    if (mode === 'default_chain') {
      if (selectedApprovers.length > 0) {
        const byStage = new Map<number, string[]>();
        selectedApprovers.forEach((a: any) => {
          const stage = Number(a?.stageOrder ?? a?.StageOrder ?? 0) || 0;
          const list = byStage.get(stage) ?? [];
          list.push(label(a));
          byStage.set(stage, list);
        });
        const stages = Array.from(byStage.entries())
          .sort((a, b) => a[0] - b[0])
          .map(([, names]) => names.join(', '));
        const chain = row?.isReportingMgrRequired ? [reportingManagerLabel(), ...stages] : stages;
        return chain.length ? chain.join(' -> ') : 'No approvers configured';
      }

      // Fallback for a default_chain row saved before §7.2 (no selectedApprovers rows yet).
      const chain: string[] = [reportingManagerLabel()];
      if (row?.isHrRequired) {
        chain.push(row?.hrAdminName ? `HR: ${row.hrAdminName}` : 'HR');
      }
      if (row?.isFinanceApproverRequired) {
        chain.push(row?.financeApproverName ? `Finance: ${row.financeApproverName}` : 'Finance');
      }
      return chain.join(' -> ');
    }

    const labels = selectedApprovers.map(label).filter((x: string) => !!x);
    if (!labels.length) return 'No approvers configured';
    return mode === 'any_one' ? `Any one of: ${labels.join(', ')}` : `Selected: ${labels.join(', ')}`;
  }

  private mapRowForGrid(row: any): any {
    const mode = this.normalizeApprovalMode(row?.approvalMode);
    const moduleKey = row?.moduleKey || this.formDocModuleMap[Number(row?.formDocNo)] || '';
    return {
      ...row,
      approvalMode: mode,
      moduleKey,
      approverSummary: this.buildApproverSummary({ ...row, approvalMode: mode }),
    };
  }

  // ✅ ADD
  AddNewHrConfig(): void {
    this.router.navigate(['editform'], { relativeTo: this.route });
  }

  // ✅ EDIT (FROM COMMON GRID)
  onEdit(row: { id?: number } | number): void {
    const id = typeof row === 'number' ? row : row?.id;

    if (id) {
      this.router.navigate(['/admin/hr-config/editform', id]);
    }
  }

  // ✅ DELETE (FROM COMMON GRID POPUP)
  onDelete(row: { id?: number } | number): void {
    const id = typeof row === 'number' ? row : row?.id;

    if (!id) return;

    this.apiservice.delete(`/api/TravelConfig/${id}`).subscribe({
      next: () => {
        this.GetAllHrConfigs(); // refresh grid
      },
      error: (err) => {
        console.error('Error deleting HR Config:', err);
      },
    });
  }
}

