712	   * a stage of only named employees stays Unanimous, same as before. */
713	  get stageGroupsPreview(): { stageOrder: number; names: string[]; isAnyOne: boolean }[] {
714	    const byStage = new Map<number, { names: string[]; isAnyOne: boolean }>();
