using Microsoft.Extensions.Logging;
using SolutionOne_BusinessLogicLayer.Services.Approval.Interface;
using SolutionOne_BusinessLogicLayer.Services.Common.Interface;
using SolutionOne_BusinessLogicLayer.Services.RBAC.Interface;
using SolutionOne_BusinessLogicLayer.Services.SystemSetting.Interface;
using SolutionOne_Core.ApprovalModels;
using SolutionOne_Core.CommonModels;
using SolutionOne_Core.Utilities;
using SolutionOne_DataAccessLayer.Repositories.Approval.Interface;
using System.Net;

namespace SolutionOne_BusinessLogicLayer.Services.Approval.Implementation
{
    public class ApprovalService : IApprovalService
    {
        private readonly IApprovalRepository _repository;
        private readonly ILogger<ApprovalService> _logger;
        private readonly IRequestMetadata _requestMetadata;
        private readonly ICurrentUserAccess _access;
        private readonly IApprovalAdminOverride _adminOverride;
        private readonly IApproverSelectorResolver _selectorResolver;

        public ApprovalService(
            IApprovalRepository repository,
            ILogger<ApprovalService> logger,
            IRequestMetadata requestMetadata,
            ICurrentUserAccess access,
            IApprovalAdminOverride adminOverride,
            IApproverSelectorResolver selectorResolver)
        {
            _repository = repository;
            _logger = logger;
            _requestMetadata = requestMetadata;
            _access = access;
            _adminOverride = adminOverride;
            _selectorResolver = selectorResolver;
        }

        private Task<long?> AdminOverrideCompanyIdAsync(long actingEmployeeId, bool superAdminAlways = false) =>
            superAdminAlways
                ? _adminOverride.GetSuperAdminCompanyIdAsync(actingEmployeeId)
                : _adminOverride.GetCompanyIdAsync(actingEmployeeId);

        public async Task<ResponseModel<ApprovalInstanceResultModel>> CreateInstance(CreateApprovalInstanceModel model)
        {
            var response = new ResponseModel<ApprovalInstanceResultModel>();
            try
            {
                var instanceId = await _repository.CreateInstanceAsync(model);

                response.IsSuccess = true;
                response.Status = HttpStatusCode.OK;
                response.Message = "Approval instance created";
                response.Data = new ApprovalInstanceResultModel { ApprovalInstanceId = instanceId };
            }
            catch (NoApprovalConfigException ex)
            {
                response.IsSuccess = false;
                response.Status = HttpStatusCode.BadRequest;
                response.Message = ex.Message;
            }
            catch (NoReportingManagerException ex)
            {
                response.IsSuccess = false;
                response.Status = HttpStatusCode.BadRequest;
                response.Message = ex.Message;
            }
            catch (NoApproversResolvedException ex)
            {
                response.IsSuccess = false;
                response.Status = HttpStatusCode.BadRequest;
                response.Message = ex.Message;
            }
            catch (Exception ex)
            {
                // Covers HR_ApprovalInstance's UQ_HR_ApprovalInstance_Transaction violation on a
                // double-submit (spec §8) along with anything unexpected - both surface as 500 with
                // the DB's own message, matching this codebase's existing generic-catch convention.
                _logger.LogError(ex, "Error creating approval instance for FormDocId={FormDocId}, TransactionRecordId={TransactionRecordId}", model.FormDocId, model.TransactionRecordId);
                response.IsSuccess = false;
                response.Status = HttpStatusCode.InternalServerError;
                response.Message = $"Could not create approval instance: {ex.Message}";
            }
            return response;
        }

        public async Task<ResponseModel<ApprovalActionResultModel>> Action(ApprovalActionModel model, bool superAdminAlways = false)
        {
            var response = new ResponseModel<ApprovalActionResultModel>();
            try
            {
                model.OverrideClosesWholeChain = superAdminAlways;
                response.Data = await _repository.ActionAsync(model, await AdminOverrideCompanyIdAsync(model.EmployeeId, superAdminAlways));
                response.IsSuccess = true;
                response.Status = HttpStatusCode.OK;
                response.Message = response.Data.OverallStatus;
            }
            catch (KeyNotFoundException ex)
            {
                response.IsSuccess = false;
                response.Status = HttpStatusCode.NotFound;
                response.Message = ex.Message;
            }
            catch (NotAuthorizedApproverException ex)
            {
                // The frontend's Approve/Reject button is already disabled for an ineligible user -
                // this is the actual server-side authorization boundary (spec §8), not a backstop UX.
                response.IsSuccess = false;
                response.Status = HttpStatusCode.Forbidden;
                response.Message = ex.Message;
            }
            catch (InstanceAlreadyClosedException ex)
            {
                response.IsSuccess = false;
                response.Status = HttpStatusCode.Conflict;
                response.Message = ex.Message;
            }
            catch (ArgumentException ex)
            {
                response.IsSuccess = false;
                response.Status = HttpStatusCode.BadRequest;
                response.Message = ex.Message;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error actioning approval instance {ApprovalInstanceId}", model.ApprovalInstanceId);
                response.IsSuccess = false;
                response.Status = HttpStatusCode.InternalServerError;
                response.Message = $"Action failed: {ex.Message}";
            }
            return response;
        }

        public async Task<ResponseModel<List<PendingApprovalModel>>> GetPending(long formDocId, long employeeId, bool superAdminAlways = false)
        {
            var response = new ResponseModel<List<PendingApprovalModel>>();
            try
            {
                var data = await _repository.GetPendingAsync(formDocId, employeeId, await AdminOverrideCompanyIdAsync(employeeId, superAdminAlways));
                response.IsSuccess = true;
                response.Status = HttpStatusCode.OK;
                response.Message = data.Any() ? "Data fetched successfully" : "No pending approvals found";
                response.Data = data;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error fetching pending approvals for FormDocId={FormDocId}, EmployeeId={EmployeeId}", formDocId, employeeId);
                response.IsSuccess = false;
                response.Status = HttpStatusCode.InternalServerError;
                response.Message = $"Could not fetch data: {ex.Message}";
                response.Data = new List<PendingApprovalModel>();
            }
            return response;
        }

        public async Task<ResponseModel<List<TeamApprovalRequestModel>>> GetTeamRequests(long formDocId, long employeeId)
        {
            var response = new ResponseModel<List<TeamApprovalRequestModel>>();
            try
            {
                var data = await _repository.GetTeamRequestsAsync(formDocId, employeeId, await AdminOverrideCompanyIdAsync(employeeId));
                response.IsSuccess = true;
                response.Status = HttpStatusCode.OK;
                response.Message = data.Any() ? "Data fetched successfully" : "No team requests found";
                response.Data = data;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error fetching team requests for FormDocId={FormDocId}, EmployeeId={EmployeeId}", formDocId, employeeId);
                response.IsSuccess = false;
                response.Status = HttpStatusCode.InternalServerError;
                response.Message = $"Could not fetch data: {ex.Message}";
                response.Data = new List<TeamApprovalRequestModel>();
            }
            return response;
        }

        public Task<long?> ResolveFormDocIdAsync(string moduleKey, string formName) =>
            _repository.ResolveFormDocIdAsync(moduleKey, formName);

        public Task<long?> GetInstanceIdAsync(long formDocId, long transactionRecordId) =>
            _repository.GetInstanceIdAsync(formDocId, transactionRecordId);

        public async Task<HashSet<long>> GetApprovedTransactionIdsAsync(long formDocId) =>
            (await _repository.GetApprovedTransactionIdsAsync(formDocId)).ToHashSet();

        private const int MaxSelectorIdsPerPreview = 100;

        public async Task<ResponseModel<ResolveSelectorResultModel>> ResolveSelector(string? selectorType, IReadOnlyList<long> selectorIds)
        {
            var response = new ResponseModel<ResolveSelectorResultModel>();

            // Admin-only: the preview lists employee names and codes. Same Admin check as the rest of
            // HR Config, now sourced from the single role store (HR_UserRoles/HR_RolesMaster).
            if (!await _access.IsAdminAsync())
                return Fail(response, HttpStatusCode.Forbidden, "Approver selectors are limited to admins.");

            var type = ApproverSelectorTypes.Normalize(selectorType);
            if (type == null || !ApproverSelectorTypes.IsGroup(type))
                return Fail(response, HttpStatusCode.BadRequest, "selectorType must be one of: role, department, designation.");

            var ids = selectorIds.Where(i => i > 0).Distinct().ToList();
            if (ids.Count == 0)
                return Fail(response, HttpStatusCode.BadRequest, "At least one selectorId is required.");
            if (ids.Count > MaxSelectorIdsPerPreview)
                return Fail(response, HttpStatusCode.BadRequest, $"At most {MaxSelectorIdsPerPreview} selectorIds per request.");

            try
            {
                var companyId = _requestMetadata.CompanyId;
                var result = new ResolveSelectorResultModel { SelectorType = type };

                foreach (var id in ids)
                {
                    var group = await _selectorResolver.ResolveGroupAsync(type, id, companyId);
                    if (group == null)
                        return Fail(response, HttpStatusCode.NotFound, $"No {type} found with id {id}.");

                    result.Groups.Add(group);
                }

                // An employee in two selected groups is listed once.
                result.Employees = result.Groups
                    .SelectMany(g => g.Employees)
                    .GroupBy(e => e.EmployeeId)
                    .Select(g => g.First())
                    .ToList();

                response.IsSuccess = true;
                response.Status = HttpStatusCode.OK;
                response.Message = $"Resolved {result.Employees.Count} employee(s).";
                response.Data = result;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error resolving {SelectorType} selector ids {SelectorIds}", type, string.Join(",", ids));
                return Fail(response, HttpStatusCode.InternalServerError, $"Could not resolve selector: {ex.Message}");
            }

            return response;
        }

        private static ResponseModel<ResolveSelectorResultModel> Fail(ResponseModel<ResolveSelectorResultModel> response, HttpStatusCode status, string message)
        {
            response.IsSuccess = false;
            response.Status = status;
            response.Message = message;
            return response;
        }

        public async Task<ResponseModel<List<ApprovalStepTimelineModel>>> GetInstanceTimeline(long approvalInstanceId)
        {
            var response = new ResponseModel<List<ApprovalStepTimelineModel>>();
            try
            {
                var data = await _repository.GetInstanceTimelineAsync(approvalInstanceId);
                response.IsSuccess = true;
                response.Status = HttpStatusCode.OK;
                response.Message = data.Any() ? "Data fetched successfully" : "No timeline found";
                response.Data = data;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error fetching timeline for approval instance {ApprovalInstanceId}", approvalInstanceId);
                response.IsSuccess = false;
                response.Status = HttpStatusCode.InternalServerError;
                response.Message = $"Could not fetch data: {ex.Message}";
                response.Data = new List<ApprovalStepTimelineModel>();
            }
            return response;
        }
    }
}

