        // approvers in the stage can still approve it"). FirstDecisionWins is the deliberate
        // exception - a single Rejected step closes the stage immediately, same as Unanimous, because
        // its whole point is "either party's decision, whichever comes first, is final."
        public static bool IsStageRejected(string stageGroupMode, IReadOnlyList<string> stepStatuses)
        {
            if (stageGroupMode is ApprovalStageGroupMode.Unanimous or ApprovalStageGroupMode.FirstDecisionWins)
                return stepStatuses.Any(s => s == ApprovalStatusNames.Rejected);

            return stepStatuses.Any(s => s == ApprovalStatusNames.Rejected)
                && stepStatuses.All(s => s is ApprovalStatusNames.Rejected or ApprovalStatusNames.Skipped);
        }
    }
}
