namespace SolutionOne_BusinessLogicLayer.Services.Approval.Implementation
{
    public class ApprovalService : IApprovalService
    {
        private readonly IApprovalRepository _repository;
        private readonly ILogger<ApprovalService> _logger;
        private readonly IRequestMetadata _requestMetadata;
        private readonly ICurrentUserAccess _access;
        private readonly IApprovalAdminOverride _adminOverride;
        private readonly IApproverSelectorResolver _selectorResolver;

        public ApprovalService(
            IApprovalRepository repository,
            ILogger<ApprovalService> logger,
            IRequestMetadata requestMetadata,
            ICurrentUserAccess access,
            IApprovalAdminOverride adminOverride,
            IApproverSelectorResolver selectorResolver)
        {
            _repository = repository;
            _logger = logger;
            _requestMetadata = requestMetadata;
            _access = access;
            _adminOverride = adminOverride;
            _selectorResolver = selectorResolver;
        }

        private Task<long?> AdminOverrideCompanyIdAsync(long actingEmployeeId, bool superAdminAlways = false) =>
            superAdminAlways
                ? _adminOverride.GetSuperAdminCompanyIdAsync(actingEmployeeId)
                : _adminOverride.GetCompanyIdAsync(actingEmployeeId);

        public async Task<ResponseModel<ApprovalInstanceResultModel>> CreateInstance(CreateApprovalInstanceModel model)
        {
            var response = new ResponseModel<ApprovalInstanceResultModel>();
            try
            {
                var instanceId = await _repository.CreateInstanceAsync(model);

                response.IsSuccess = true;
                response.Status = HttpStatusCode.OK;
                response.Message = "Approval instance created";
                response.Data = new ApprovalInstanceResultModel { ApprovalInstanceId = instanceId };
            }
            catch (NoApprovalConfigException ex)
            {
                response.IsSuccess = false;
                response.Status = HttpStatusCode.BadRequest;
                response.Message = ex.Message;
            }
            catch (NoReportingManagerException ex)
            {
                response.IsSuccess = false;
                response.Status = HttpStatusCode.BadRequest;
                response.Message = ex.Message;
            }
            catch (NoApproversResolvedException ex)
            {
                response.IsSuccess = false;
                response.Status = HttpStatusCode.BadRequest;
                response.Message = ex.Message;
            }
            catch (Exception ex)
            {
                // Covers HR_ApprovalInstance's UQ_HR_ApprovalInstance_Transaction violation on a
                // double-submit (spec §8) along with anything unexpected - both surface as 500 with
                // the DB's own message, matching this codebase's existing generic-catch convention.
                _logger.LogError(ex, "Error creating approval instance for FormDocId={FormDocId}, TransactionRecordId={TransactionRecordId}", model.FormDocId, model.TransactionRecordId);
                response.IsSuccess = false;
                response.Status = HttpStatusCode.InternalServerError;
                response.Message = $"Could not create approval instance: {ex.Message}";
            }
            return response;
        }

        public async Task<ResponseModel<ApprovalActionResultModel>> Action(ApprovalActionModel model, bool superAdminAlways = false)
        {
            var response = new ResponseModel<ApprovalActionResultModel>();
            try
            {
                model.OverrideClosesWholeChain = superAdminAlways;
                response.Data = await _repository.ActionAsync(model, await AdminOverrideCompanyIdAsync(model.EmployeeId, superAdminAlways));
                response.IsSuccess = true;
                response.Status = HttpStatusCode.OK;
                response.Message = response.Data.OverallStatus;
            }
            catch (KeyNotFoundException ex)
            {
                response.IsSuccess = false;
                response.Status = HttpStatusCode.NotFound;
                response.Message = ex.Message;
            }
            catch (NotAuthorizedApproverException ex)
            {
                // The frontend's Approve/Reject button is already disabled for an ineligible user -
                // this is the actual server-side authorization boundary (spec §8), not a backstop UX.
                response.IsSuccess = false;
                response.Status = HttpStatusCode.Forbidden;
                response.Message = ex.Message;
            }
            catch (InstanceAlreadyClosedException ex)
            {
                response.IsSuccess = false;
                response.Status = HttpStatusCode.Conflict;
                response.Message = ex.Message;
            }
            catch (ArgumentException ex)
            {
                response.IsSuccess = false;
                response.Status = HttpStatusCode.BadRequest;
                response.Message = ex.Message;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error actioning approval instance {ApprovalInstanceId}", model.ApprovalInstanceId);
                response.IsSuccess = false;
                response.Status = HttpStatusCode.InternalServerError;
                response.Message = $"Action failed: {ex.Message}";
            }
            return response;
        }

