            catch (Exception ex)
            {
                _logger.LogError(ex, "Error fetching timeline for approval instance {ApprovalInstanceId}", approvalInstanceId);
                response.IsSuccess = false;
                response.Status = HttpStatusCode.InternalServerError;
                response.Message = $"Could not fetch data: {ex.Message}";
                response.Data = new List<ApprovalStepTimelineModel>();
            }
            return response;
        }
    }
