private async Task<List<StepInsert>> BuildStepsAsync(CreateApprovalInstanceModel request, ApprovalConfigRow config)
{
    var mode = ApprovalModes.Normalize(config.ApprovalMode);
    var steps = new List<StepInsert>();

    if (mode == ApprovalModes.DefaultChain)
    {
        var stage = 0;
        if (config.IsReportingMgrRequired)
        {
            var (rm, isFallback) = await ResolveReportingManagerAsync(request.RequestorEmployeeId, config.FallbackApproverEmpId);
            if (rm is null)
                throw new NoReportingManagerException(request.RequestorEmployeeId);
            steps.Add(new StepInsert(stage++, ApprovalStageKind.ReportingManager, ApprovalStageGroupMode.Unanimous, rm.Value, isFallback));
        }

        // Every configured approver, whatever free-text type/Designation it carries (HR,
        // Finance, Logistics, Legal, ...) - replaces the old fixed "one HR approver, one
        // Finance approver" read off HR_ApprovalConfig.HrApproverId/FinanceApproverId. Rows
        // sharing a StageOrder run together as one Unanimous stage; stages advance in
        // ascending StageOrder order, after the Reporting Manager stage (if any).
        // A stage holding any group selector (role/department/designation) is AnyOne instead -
        // see ApproverSelectorRules.ResolveStageMode.
        var approvers = await ResolveConfigApproversAsync(config.ApprovalConfigId, request, keepStageOrder: true);
        foreach (var group in approvers.GroupBy(a => a.StageOrder).OrderBy(g => g.Key))
        {
            var stageMode = ApproverSelectorRules.ResolveStageMode(ApprovalStageGroupMode.Unanimous, group.Any(a => a.FromGroup));
            foreach (var a in group)
                steps.Add(new StepInsert(stage, ApprovalStageKind.Custom, stageMode, a.EmployeeId));
            stage++;
        }

        return steps;
    }

    if (mode == ApprovalModes.AnyOne)
    {
        var anyOneStage = 0;
        if (config.IsReportingMgrRequired)
        {
            var (rm, isFallback) = await ResolveReportingManagerAsync(request.RequestorEmployeeId, config.FallbackApproverEmpId);
            if (rm is null)
                throw new NoReportingManagerException(request.RequestorEmployeeId);
            steps.Add(new StepInsert(0, ApprovalStageKind.ReportingManager, ApprovalStageGroupMode.Unanimous, rm.Value, isFallback));
            anyOneStage = 1;
        }

        var approvers = await ResolveConfigApproversAsync(config.ApprovalConfigId, request, keepStageOrder: false);
        foreach (var a in approvers)
            steps.Add(new StepInsert(anyOneStage, ApprovalStageKind.Custom, ApprovalStageGroupMode.AnyOne, a.EmployeeId));

        return steps;
    }

    if (mode == ApprovalModes.FirstDecisionWins)
    {
        // Single stage (StageOrder 0): Reporting Manager (if resolvable) plus the whole
        // configured approver pool, together - whichever of them decides first, Approve or
        // Reject, closes it. Unlike default_chain/any_one, a missing Reporting Manager is NOT
        // fatal here - ReportingPersonID legitimately being unset is a real, expected case for
        // Attendance Adjustment (see AttendanceAdjustmentRepository's own "0 rather than null"
        // comment), and the pool alone is meant to cover that case, matching the legacy
        // message "only HR can approve it."
        if (config.IsReportingMgrRequired)
        {
            var (rm, isFallback) = await ResolveReportingManagerAsync(request.RequestorEmployeeId, config.FallbackApproverEmpId);
            if (rm is not null)
                steps.Add(new StepInsert(0, ApprovalStageKind.ReportingManager, ApprovalStageGroupMode.FirstDecisionWins, rm.Value, isFallback));
        }

        var pool = await ResolveConfigApproversAsync(config.ApprovalConfigId, request, keepStageOrder: false);
        foreach (var a in pool)
            steps.Add(new StepInsert(0, ApprovalStageKind.Custom, ApprovalStageGroupMode.FirstDecisionWins, a.EmployeeId));

        return steps;
    }

    // selected_employee_override
    var selected = await ResolveConfigApproversAsync(config.ApprovalConfigId, request, keepStageOrder: false);
    var selectedMode = ApproverSelectorRules.ResolveStageMode(ApprovalStageGroupMode.Unanimous, selected.Any(a => a.FromGroup));
    foreach (var a in selected)
        steps.Add(new StepInsert(0, ApprovalStageKind.Custom, selectedMode, a.EmployeeId));

    return steps;
}

#endregion

#region Action

public async Task<ApprovalActionResultModel> ActionAsync(ApprovalActionModel request, long? adminOverrideCompanyId = null)
{
    var decision = (request.Decision ?? string.Empty).Trim();
    if (decision != ApprovalStatusNames.Approved && decision != ApprovalStatusNames.Rejected)
        throw new ArgumentException("Decision must be 'Approved' or 'Rejected'.", nameof(request));

    await _ctxt.BeginTransactionAsync();
    try
    {
        var statusIds = await GetStatusIdsAsync();

        var instance = await _dapper.QueryFirstOrDefaultAsync<InstanceLockRow>(
            "SELECT ApprovalInstanceId, CurrentStageOrder, OverallStatusId, CompanyMasterId FROM HR_ApprovalInstance WITH (UPDLOCK, ROWLOCK) WHERE ApprovalInstanceId = @id",
            new { id = request.ApprovalInstanceId });

        if (instance == null)
            throw new KeyNotFoundException($"Approval instance {request.ApprovalInstanceId} not found.");

        if (instance.OverallStatusId != statusIds[ApprovalStatusNames.Pending])
        {
            var currentStatusName = await _dapper.QueryFirstOrDefaultAsync<string>(
                "SELECT Status FROM HR_ApprovalStatusMaster WHERE Id = @id", new { id = instance.OverallStatusId }) ?? "Unknown";
            throw new InstanceAlreadyClosedException(request.ApprovalInstanceId, currentStatusName);
        }

        if (request.OverrideClosesWholeChain && adminOverrideCompanyId is not null && instance.CompanyMasterId == adminOverrideCompanyId)
        {
            var closed = await CloseWholeChainAsync(request, instance, decision, statusIds);
            await _ctxt.CommitAsync();
            return closed;
        }

        var step = await _dapper.QueryFirstOrDefaultAsync<StepLockRow>(@"
            SELECT ApprovalStepId, StageGroupMode
            FROM HR_ApprovalStep WITH (UPDLOCK, ROWLOCK)
            WHERE ApprovalInstanceId = @id AND StageOrder = @stage AND ApproverEmployeeId = @employeeId AND StatusId = @pendingId",
            new
            {
                id = request.ApprovalInstanceId,
                stage = instance.CurrentStageOrder,
                employeeId = request.EmployeeId,
                pendingId = statusIds[ApprovalStatusNames.Pending]
            });

        if (step != null)
        {
            await _dapper.ExecuteAsync(
                "UPDATE HR_ApprovalStep SET StatusId = @statusId, ActionedDate = SYSUTCDATETIME(), Remarks = @remarks WHERE ApprovalStepId = @id",
                new { statusId = statusIds[decision], remarks = request.Remarks, id = step.ApprovalStepId });
        }
        else
        {
            // Admin override: no step of the caller's own, but the company has switched
            // Approval.AdminOverride on and the caller is an admin (decided upstream). One
            // admin decision closes the stage - every still-Pending step in it takes the
            // decision, stamped with who really pressed the button. A caller who IS an assigned
            // approver never gets here; they act through their own step above.
            if (adminOverrideCompanyId is null || instance.CompanyMasterId != adminOverrideCompanyId)
                throw new NotAuthorizedApproverException(request.ApprovalInstanceId, request.EmployeeId);

            var pendingSteps = (await _dapper.QueryAsync<StepLockRow>(@"
                SELECT ApprovalStepId, StageGroupMode
                FROM HR_ApprovalStep WITH (UPDLOCK, ROWLOCK)
                WHERE ApprovalInstanceId = @id AND StageOrder = @stage AND StatusId = @pendingId",
                new { id = request.ApprovalInstanceId, stage = instance.CurrentStageOrder, pendingId = statusIds[ApprovalStatusNames.Pending] })).ToList();

            if (pendingSteps.Count == 0)
                throw new NotAuthorizedApproverException(request.ApprovalInstanceId, request.EmployeeId);

            step = pendingSteps[0];
            await _dapper.ExecuteAsync(@"
                UPDATE HR_ApprovalStep
                SET StatusId = @statusId, ActionedDate = SYSUTCDATETIME(), Remarks = @remarks, ActionedByEmployeeId = @actor
                WHERE ApprovalInstanceId = @id AND StageOrder = @stage AND StatusId = @pendingId",
                new
                {
                    statusId = statusIds[decision], remarks = request.Remarks, actor = request.EmployeeId,
                    id = request.ApprovalInstanceId, stage = instance.CurrentStageOrder, pendingId = statusIds[ApprovalStatusNames.Pending]
                });
        }

        var stageStatusNames = (await _dapper.QueryAsync<string>(@"
            SELECT sm.Status
            FROM HR_ApprovalStep s
            INNER JOIN HR_ApprovalStatusMaster sm ON sm.Id = s.StatusId
            WHERE s.ApprovalInstanceId = @id AND s.StageOrder = @stage",
            new { id = request.ApprovalInstanceId, stage = instance.CurrentStageOrder })).ToList();

        var result = decision == ApprovalStatusNames.Rejected
            ? await HandleRejectionAsync(request.ApprovalInstanceId, instance.CurrentStageOrder, step.StageGroupMode, stageStatusNames, statusIds)
            : await HandleApprovalAsync(request.ApprovalInstanceId, instance.CurrentStageOrder, step.StageGroupMode, stageStatusNames, statusIds);

        await _ctxt.CommitAsync();
        return result;
    }
    catch
    {
        await _ctxt.RollbackAsync();
        throw;
    }
}

// Super-admin decision that settles the whole approval: the current stage's pending steps take
// the decision (stamped with who pressed the button), every other Pending step - later stages,
// co-approvers - is Skipped, and the instance closes with the same outcome.
private async Task<ApprovalActionResultModel> CloseWholeChainAsync(
    ApprovalActionModel request, InstanceLockRow instance, string decision, Dictionary<string, long> statusIds)
{
    var decided = await _dapper.ExecuteAsync(@"
        UPDATE HR_ApprovalStep
        SET StatusId = @statusId, ActionedDate = SYSUTCDATETIME(), Remarks = @remarks, ActionedByEmployeeId = @actor
        WHERE ApprovalInstanceId = @id AND StageOrder = @stage AND StatusId = @pendingId",
        new
        {
            statusId = statusIds[decision], remarks = request.Remarks, actor = request.EmployeeId,
            id = request.ApprovalInstanceId, stage = instance.CurrentStageOrder, pendingId = statusIds[ApprovalStatusNames.Pending]
        });

    if (decided == 0)
        throw new NotAuthorizedApproverException(request.ApprovalInstanceId, request.EmployeeId);

    var skipped = await _dapper.ExecuteAsync(@"
        UPDATE HR_ApprovalStep
        SET StatusId = @skippedId, ActionedDate = SYSUTCDATETIME(), ActionedByEmployeeId = @actor,
            Remarks = N'Skipped - closed by administrator override'
        WHERE ApprovalInstanceId = @id AND StatusId = @pendingId",
        new { skippedId = statusIds[ApprovalStatusNames.Skipped], actor = request.EmployeeId, id = request.ApprovalInstanceId, pendingId = statusIds[ApprovalStatusNames.Pending] });

    var outcome = decision == ApprovalStatusNames.Approved ? ApprovalStatusNames.Approved : ApprovalStatusNames.Rejected;
    await CloseInstanceAsync(request.ApprovalInstanceId, statusIds[outcome]);

    return new ApprovalActionResultModel
    {
        OverallStatus = outcome, CurrentStageOrder = instance.CurrentStageOrder,
        IsAdminOverride = true, SkippedStepCount = skipped
    };
}

private async Task<ApprovalActionResultModel> HandleRejectionAsync(
    long approvalInstanceId, int currentStage, string stageGroupMode, List<string> stageStatusNames, Dictionary<string, long> statusIds)
{
    if (!ApprovalStepEvaluator.IsStageRejected(stageGroupMode, stageStatusNames))
        return new ApprovalActionResultModel { OverallStatus = ApprovalStatusNames.Pending, CurrentStageOrder = currentStage };

    await _dapper.ExecuteAsync(
        "UPDATE HR_ApprovalStep SET StatusId = @skippedId WHERE ApprovalInstanceId = @id AND StatusId = @pendingId",
        new { skippedId = statusIds[ApprovalStatusNames.Skipped], id = approvalInstanceId, pendingId = statusIds[ApprovalStatusNames.Pending] });

    await CloseInstanceAsync(approvalInstanceId, statusIds[ApprovalStatusNames.Rejected]);
    return new ApprovalActionResultModel { OverallStatus = ApprovalStatusNames.Rejected, CurrentStageOrder = currentStage };
}

private async Task<ApprovalActionResultModel> HandleApprovalAsync(
    long approvalInstanceId, int currentStage, string stageGroupMode, List<string> stageStatusNames, Dictionary<string, long> statusIds)
{
    if (!ApprovalStepEvaluator.IsStageApproved(stageGroupMode, stageStatusNames))
        return new ApprovalActionResultModel { OverallStatus = ApprovalStatusNames.Pending, CurrentStageOrder = currentStage };

    if (stageGroupMode is ApprovalStageGroupMode.AnyOne or ApprovalStageGroupMode.FirstDecisionWins)
    {
        await _dapper.ExecuteAsync(
            "UPDATE HR_ApprovalStep SET StatusId = @skippedId WHERE ApprovalInstanceId = @id AND StageOrder = @stage AND StatusId = @pendingId",
            new { skippedId = statusIds[ApprovalStatusNames.Skipped], id = approvalInstanceId, stage = currentStage, pendingId = statusIds[ApprovalStatusNames.Pending] });
    }

    var nextStage = await _dapper.QueryFirstOrDefaultAsync<int?>(
        "SELECT MIN(StageOrder) FROM HR_ApprovalStep WHERE ApprovalInstanceId = @id AND StageOrder > @stage",
        new { id = approvalInstanceId, stage = currentStage });

    if (nextStage is null)
    {
        await CloseInstanceAsync(approvalInstanceId, statusIds[ApprovalStatusNames.Approved]);
        return new ApprovalActionResultModel { OverallStatus = ApprovalStatusNames.Approved, CurrentStageOrder = currentStage };
    }

    await _dapper.ExecuteAsync(
        "UPDATE HR_ApprovalInstance SET CurrentStageOrder = @next WHERE ApprovalInstanceId = @id",
        new { next = nextStage.Value, id = approvalInstanceId });

    return new ApprovalActionResultModel { OverallStatus = ApprovalStatusNames.Pending, CurrentStageOrder = nextStage.Value };
}

private Task CloseInstanceAsync(long approvalInstanceId, long statusId) => _dapper.ExecuteAsync(
    "UPDATE HR_ApprovalInstance SET OverallStatusId = @statusId, CompletedDate = SYSUTCDATETIME() WHERE ApprovalInstanceId = @id",
    new { statusId, id = approvalInstanceId });

#endregion

#region Lists / timeline / lookups

public async Task<List<PendingApprovalModel>> GetPendingAsync(long formDocId, long employeeId, long? adminOverrideCompanyId = null)

