import { CommonModule } from '@angular/common';
import { RouterModule, Routes } from '@angular/router';
import { canActivateEmployeeOnly } from '../../services/employee-required.guard';
import { FnfConfigComponent } from './config/config.component';
import { FnfAlumniListComponent } from './alumni/list/list.component';
import { FnfSettlementListComponent } from './settlement/list/list.component';
