})
export class FnfModule {}
import { CommonModule } from '@angular/common';
import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { finalize } from 'rxjs/operators';
import { CommonGridComponent } from '../../../../layout/common-grid/common-grid.component';
import { AuthService } from '../../../../services/auth.service';
import { ChipNavigationService } from '../../../../services/ChipNavigation.service';
import { ToastService } from '../../../../services/toaster.service';
import { FnfCaseModel } from '../../models/fnf.model';
import { FnfApiService } from '../../services/fnf-api.service';

/** A different person reviews and approves/rejects a submitted case. */
@Component({
  selector: 'app-fnf-approval-list',
  standalone: true,
  imports: [CommonModule, CommonGridComponent],
  templateUrl: './list.component.html',
})
export class FnfApprovalListComponent implements OnInit {
  columns: Record<string, unknown>[] = [];
  data: FnfCaseModel[] = [];
  isLoading = false;

  constructor(
    private authService: AuthService,
    private fnfApi: FnfApiService,
    private toast: ToastService,
    private router: Router,
    private chipService: ChipNavigationService,
  ) {
    this.authService.ScreenName = 'F&F Approval';
    this.chipService.addTab({ title: 'F&F Approval', route: '/fnf/approval' });
  }

  ngOnInit(): void {
    this.columns = [
      { dataField: 'caseNo', caption: 'Case No.', width: 130 },
      { dataField: 'employeeName', caption: 'Employee' },
      { dataField: 'employeeCode', caption: 'Code', width: 100 },
      { dataField: 'lastWorkingDate', caption: 'LWD', dataType: 'date', format: 'dd-MMM-yyyy', width: 120 },
      { dataField: 'totalEarnings', caption: 'Earnings', dataType: 'number', format: { type: 'fixedPoint', precision: 2 }, width: 120 },
      { dataField: 'totalDeductions', caption: 'Deductions', dataType: 'number', format: { type: 'fixedPoint', precision: 2 }, width: 120 },
      { dataField: 'netPayable', caption: 'Net Payable', dataType: 'number', format: { type: 'fixedPoint', precision: 2 }, width: 130 },
      {
        type: 'buttons',
        caption: 'Actions',
        width: 90,
        buttons: [{ hint: 'Review', text: 'Review', onClick: (e: any) => this.review(e.row?.data) }],
      },
    ];
    this.load();
  }

  get gridSubtitle(): string {
    const n = this.data.length;
    return `${n} case${n === 1 ? '' : 's'} awaiting your decision`;
  }

  load(): void {
    this.isLoading = true;
    this.fnfApi
      .getPendingCases()
      .pipe(finalize(() => (this.isLoading = false)))
      .subscribe({
        next: (res) => {
          if (!FnfApiService.isOk(res)) {
            this.data = [];
            this.toast.error(FnfApiService.messageOf(res, 'Failed to load pending cases.'));
            return;
          }
          const rows = FnfApiService.dataOf<FnfCaseModel[]>(res);
          this.data = (Array.isArray(rows) ? rows : []).filter((c) => c.workflowStatus === 'Submitted');
        },
        error: (err) => {
          this.data = [];
          this.toast.error(FnfApiService.errorMessage(err, 'Failed to load pending cases.'));
        },
      });
  }

  review(row: FnfCaseModel): void {
    this.router.navigate(['/fnf/approval/case', row.fnfSettlementId]);
  }
}
import { CommonModule } from '@angular/common';
import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { DxButtonModule, DxNumberBoxModule, DxPopupModule, DxSelectBoxModule, DxTextAreaModule } from 'devextreme-angular';
import { finalize } from 'rxjs/operators';
import { CommonGridComponent } from '../../../../layout/common-grid/common-grid.component';
import { AuthService } from '../../../../services/auth.service';
import { ChipNavigationService } from '../../../../services/ChipNavigation.service';
import { ToastService } from '../../../../services/toaster.service';
import { FnfCaseModel, FnfCheckModel, FnfSettlementDetailModel } from '../../models/fnf.model';
import { FnfApiService } from '../../services/fnf-api.service';

const MONTHS = [
  { value: 1, text: 'January' }, { value: 2, text: 'February' }, { value: 3, text: 'March' },
  { value: 4, text: 'April' }, { value: 5, text: 'May' }, { value: 6, text: 'June' },
  { value: 7, text: 'July' }, { value: 8, text: 'August' }, { value: 9, text: 'September' },
  { value: 10, text: 'October' }, { value: 11, text: 'November' }, { value: 12, text: 'December' },
];

/** Read-only case review except for the decision itself: approve (pushes money into payroll) or reject (back to Draft). */
@Component({
  selector: 'app-fnf-approval-case',
  standalone: true,
  imports: [CommonModule, CommonGridComponent, DxPopupModule, DxSelectBoxModule, DxNumberBoxModule, DxTextAreaModule, DxButtonModule],
  templateUrl: './case.component.html',
})
export class FnfApprovalCaseComponent implements OnInit {
  caseId = 0;
  case: FnfCaseModel | null = null;
  loading = false;

  settlementDetails: FnfSettlementDetailModel[] = [];
  settlementColumns: Record<string, unknown>[] = [];

  parameters: FnfCheckModel[] = [];
  parameterColumns: Record<string, unknown>[] = [];

  months = MONTHS;
  decisionMonth: number | null = null;
  decisionYear: number | null = null;
  rejectReason = '';

  approveBusy = false;
  rejectBusy = false;

  // ---------------------------------------------------------- Parameter popup
  paramPopupVisible = false;
  paramBusy = false;
  paramPopupRow: FnfCheckModel | null = null;
  paramResult: string | null = null;
  paramRemarks = '';

  constructor(
    private authService: AuthService,
    private fnfApi: FnfApiService,
    private toast: ToastService,
    private route: ActivatedRoute,
    private router: Router,
    private chipService: ChipNavigationService,
  ) {
    this.authService.ScreenName = 'F&F Approval';
  }

  ngOnInit(): void {
    this.caseId = Number(this.route.snapshot.paramMap.get('id') ?? 0);
    this.chipService.addTab({ title: 'F&F Approval', route: `/fnf/approval/case/${this.caseId}` });

    this.settlementColumns = [
      { dataField: 'componentType', caption: 'Component' },
      { dataField: 'addDeduct', caption: 'Add/Deduct', width: 100 },
      { dataField: 'days', caption: 'Days', dataType: 'number', width: 80 },
      { dataField: 'rate', caption: 'Rate', dataType: 'number', format: { type: 'fixedPoint', precision: 2 }, width: 100 },
      { dataField: 'amount', caption: 'Amount', dataType: 'number', format: { type: 'fixedPoint', precision: 2 }, width: 120 },
      { dataField: 'remarks', caption: 'Remarks / Basis' },
    ];

    this.parameterColumns = [
      { dataField: 'checkName', caption: 'Parameter' },
      { dataField: 'policyStandard', caption: 'Policy / Standard' },
      { dataField: 'actualValue', caption: 'Actual', width: 100 },
      {
        dataField: 'result',
        caption: 'Result',
        width: 120,
        cellTemplate: (container: HTMLElement, options: any) => {
          const span = document.createElement('span');
          const result = options.data?.result;
          const cls = result === 'Pass' ? 'status-approved' : result === 'Fail' ? 'status-rejected' : 'status-hold';
          span.className = `status-pill ${cls}`;
          span.innerText = result || 'Not answered';
          container.appendChild(span);
        },
      },
      { dataField: 'remarks', caption: 'Remarks' },
    ];

    this.load();
  }

  load(): void {
    if (!this.caseId) return;
    this.loading = true;
    this.fnfApi
      .getApprovalCase(this.caseId)
      .pipe(finalize(() => (this.loading = false)))
      .subscribe({
        next: (res) => {
          if (!FnfApiService.isOk(res)) {
            this.toast.error(FnfApiService.messageOf(res, 'Failed to load case.'));
            return;
          }
          this.case = FnfApiService.dataOf<FnfCaseModel>(res);
          this.decisionMonth = this.case.settlementMonth;
          this.decisionYear = this.case.settlementYear ?? new Date().getFullYear();
        },
        error: (err) => this.toast.error(FnfApiService.errorMessage(err, 'Failed to load case.')),
      });

    this.fnfApi.getSettlementDetails(this.caseId).subscribe({
      next: (res) => {
        const rows = FnfApiService.dataOf<FnfSettlementDetailModel[]>(res);
        this.settlementDetails = Array.isArray(rows) ? rows : [];
      },
    });

    this.loadParameters();
  }

  private loadParameters(): void {
    this.fnfApi.getApprovalParameters(this.caseId).subscribe({
      next: (res) => {
        const rows = FnfApiService.dataOf<FnfCheckModel[]>(res);
        this.parameters = Array.isArray(rows) ? [...rows].sort((a, b) => a.sortOrder - b.sortOrder) : [];
      },
    });
  }

  goBack(): void {
    this.router.navigate(['/fnf/approval']);
  }

  get isBlocked(): boolean {
    if (!this.case) return true;
    if (this.case.workflowStatus !== 'Submitted') return true;
    return this.parameters.some((p) => p.isRequired && p.result !== 'Pass' && p.result !== 'NA');
  }

  approve(): void {
    if (!this.decisionMonth || !this.decisionYear) {
      this.toast.error('Choose the payroll month and year to pay this into.');
      return;
    }
    if (
      !confirm(
        'Approve this settlement? The amounts will be pushed into the selected payroll month and the loan schedule closed. This cannot be undone here.',
      )
    )
      return;

    this.approveBusy = true;
    this.fnfApi
      .approveCase(this.caseId, { month: this.decisionMonth, year: this.decisionYear })
      .pipe(finalize(() => (this.approveBusy = false)))
      .subscribe({
        next: (res) => {
          if (!FnfApiService.isOk(res)) {
            this.toast.error(FnfApiService.messageOf(res, 'Approve failed.'));
            return;
          }
          this.toast.success(FnfApiService.messageOf(res, 'Approved.'));
          this.goBack();
        },
        // Interceptor toasts the reason (403/409 from the approval engine, etc.) — toasting
        // errorMessage() here too was double-showing the same message.
        error: () => {},
      });
  }

  reject(): void {
    if (!this.rejectReason.trim()) {
      this.toast.error('Say why you are returning it — the preparer needs the reason.');
      return;
    }
    if (!confirm('Return this settlement to the preparer?')) return;

    this.rejectBusy = true;
    this.fnfApi
      .rejectCase(this.caseId, { reason: this.rejectReason.trim() })
      .pipe(finalize(() => (this.rejectBusy = false)))
      .subscribe({
        next: (res) => {
          if (!FnfApiService.isOk(res)) {
            this.toast.error(FnfApiService.messageOf(res, 'Reject failed.'));
            return;
          }
          this.toast.success(FnfApiService.messageOf(res, 'Returned to the preparer as a draft.'));
          this.goBack();
        },
        // Interceptor toasts the reason (403/409 from the approval engine, etc.) — toasting
        // errorMessage() here too was double-showing the same message.
        error: () => {},
      });
  }

  // ------------------------------------------------------------- Parameters

  openParamEdit(row: FnfCheckModel): void {
    this.paramPopupRow = row;
    this.paramResult = row.result;
    this.paramRemarks = row.remarks ?? '';
    this.paramPopupVisible = true;
  }

  saveParam(): void {
    if (!this.paramPopupRow) return;
    this.paramBusy = true;
    this.fnfApi
      .updateCheck(this.caseId, { fnfCheckId: this.paramPopupRow.fnfCheckId, result: this.paramResult, remarks: this.paramRemarks })
      .pipe(finalize(() => (this.paramBusy = false)))
      .subscribe({
        next: (res) => {
          if (!FnfApiService.isOk(res)) {
            this.toast.error(FnfApiService.messageOf(res, 'Could not update.'));
            return;
          }
          this.paramPopupVisible = false;
          this.loadParameters();
        },
        error: (err) => this.toast.error(FnfApiService.errorMessage(err, 'Could not update.')),
      });
  }
}
