import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { finalize } from 'rxjs/operators';
import {
  DxButtonModule,
  DxNumberBoxModule,
  DxPopupModule,
  DxSelectBoxModule,
  DxTextAreaModule,
} from 'devextreme-angular';
import { CommonGridComponent } from '../../../../layout/common-grid/common-grid.component';
import { ChipNavigationService } from '../../../../services/ChipNavigation.service';
import { AuthService } from '../../../../services/auth.service';
import { ToastService } from '../../../../services/toaster.service';
import { IncomeTaxApiService, LookupOption } from '../../services/income-tax-api.service';
import {
  APPROVAL_STATUS_OPTIONS,
  IncomeTaxApprovalQueueRow,
  IncomeTaxApprovalStatus,
  IncomeTaxProofFile,
  IncomeTaxProofSubmission,
  IncomeTaxSubmissionFile,
  approvalStatusBadgeClass,
  approvalStatusLabel,
} from '../../models/income-tax.model';

/**
 * The approver's review queue — one row per proof submission. Rows with no
 * decision yet come back as Pending with a null `approvalId`.
 */
@Component({
  selector: 'app-income-tax-proof-approval-queue',
  standalone: true,
  imports: [
    CommonModule,
    CommonGridComponent,
    DxPopupModule,
    DxSelectBoxModule,
    DxNumberBoxModule,
    DxTextAreaModule,
    DxButtonModule,
  ],
  templateUrl: './queue.component.html',
  styleUrl: '../../shared/income-tax-page.scss',
})
export class ProofApprovalQueueComponent implements OnInit {
  columns: Record<string, unknown>[] = [];
  data: Record<string, unknown>[] = [];
  isLoading = false;

  // Filters — all optional, mirroring the legacy approval page's branch/category pair.
  branches: LookupOption[] = [];
  categories: LookupOption[] = [];
  statusOptions = [{ id: null as number | null, name: 'All statuses' }, ...APPROVAL_STATUS_OPTIONS];
  branchMasterId: number | null = null;
  categoryMasterId: number | null = null;
  approvalStatusFilter: number | null = null;

  // Review popup
  popupVisible = false;
  isDetailLoading = false;
  isSaving = false;
  selectedRow: IncomeTaxApprovalQueueRow | null = null;
  detail: IncomeTaxProofSubmission | null = null;
  /** 0 means "leave it at the submitted amount" — the Save call omits it then. */
  approvedAmount = 0;
  approvalRemarks = '';

  constructor(
    private chipService: ChipNavigationService,
    private authService: AuthService,
    private incomeTax: IncomeTaxApiService,
    private toast: ToastService,
  ) {
    this.authService.ScreenName = 'Income Tax Proof Approval';
    this.chipService.addTab({
      title: 'Income Tax Proof Approval',
      route: '/income-tax/proof-approval',
    });
  }

  ngOnInit(): void {
    this.columns = [
      { dataField: 'approvalStatusLabel', caption: 'Approval Status', width: 140 },
      { dataField: 'submissionCode', caption: 'Submission Code', width: 140 },
      { dataField: 'employeeName', caption: 'Employee' },
      { dataField: 'headName', caption: 'Income Tax Head' },
      { dataField: 'sectionName', caption: 'Section', width: 120 },
      {
        dataField: 'declarationAmount',
