public async Task<ResponseModel> GetQueueAsync(IncomeTaxApprovalQueueFilterDto filter)
{
    var res = new ResponseModel();
    try
    {
        var queue = await _repo.GetQueueAsync(filter, _meta.CompanyId);

        // Approval Engine visibility filter (docs/dev-tracking/approval.md Phase 11) - this
        // screen previously had NO caller-scoping at all beyond the two optional Branch/Category
        // query params, so any authenticated user could see every pending submission. Filtered
        // unconditionally to what's actually Pending on the caller right now, via the engine's
        // real per-item resolution - same GetPending-based mechanism as Recruitment's
        // applyApproverFilter (RecruitmentRequisitionService.GetAllRecruitmentRequisitions),
        // which also has NO role-based exemption - an Admin only sees what their own employee
        // record is the configured approver for, same as anyone else. If a company-wide
        // oversight view turns out to be wanted later, that should be its own explicit,
        // caller-requested mode (like Recruitment's own `applyApproverFilter` toggle), not a
        // silent role-based bypass baked into this one.
        var formDocId = await _approvalService.ResolveFormDocIdAsync(ApprovalModuleKeys.IncomeTax, IncomeTaxFormDocNames.ProofApproval);
        var pendingIds = formDocId is null
            ? new HashSet<long>()
            : (await _approvalService.GetPending(formDocId.Value, _meta.EmployeeMasterId)).Data?
                .Select(p => p.TransactionRecordId).ToHashSet() ?? new HashSet<long>();

        queue = queue.Where(q => pendingIds.Contains(q.SubmissionID)).ToList();

        return res.FastRet(true, HttpStatusCode.OK, "Fetched approval queue.", queue, null);
    }
    catch (Exception e)
    {
        _logger.LogError(e, "[{Layer}]: Exception while fetching approval queue", _LayerName);
        return res.FastRet(false, HttpStatusCode.InternalServerError, "Failed to fetch approval queue.", null, null);
    }
}

        // same scoped IDapperContext and nesting one inside the other would silently corrupt the
        // connection (the same hazard already hit and fixed for Trip Approval).
        if (dto.ApprovalStatus is IncomeTaxApprovalStatus.Approved or IncomeTaxApprovalStatus.Rejected)
        {
            var formDocId = await _approvalService.ResolveFormDocIdAsync(ApprovalModuleKeys.IncomeTax, IncomeTaxFormDocNames.ProofApproval);
            var instanceId = formDocId is null ? null : await _approvalService.GetInstanceIdAsync(formDocId.Value, dto.SubmissionID);

            if (instanceId is not null)
            {
                var actionResult = await _approvalService.Action(new ApprovalActionModel
                {
                    ApprovalInstanceId = instanceId.Value,
                    EmployeeId = _meta.EmployeeMasterId,
                    Decision = dto.ApprovalStatus == IncomeTaxApprovalStatus.Approved ? ApprovalStatusNames.Approved : ApprovalStatusNames.Rejected,
                    Remarks = dto.ApprovalRemarks,
                });

                // IApprovalService.Action wraps NotAuthorizedApproverException/
                // InstanceAlreadyClosedException into a failed ResponseModel itself - it never
                // throws them, so the gate must check IsSuccess, not catch.
                if (!actionResult.IsSuccess)
                    return res.FastRet(false, actionResult.Status, actionResult.Message, null, null);
            }
            // else: no instance for this submission (submitted before this migration, or the
            // config gap was never fixed) - falls through unguarded, same as every submission
            // behaved before this migration (there was no authorization at all).
        }

        await _repo.UpsertAsync(dto, submission.EmployeeMasterID, submission.ActualAmount ?? 0m, _meta.UserId, _meta.CompanyId);

    {
        _logger.LogError(e, "[{Layer}]: Exception while deleting proof file {Id}", _LayerName, fileId);
        return res.FastRet(false, HttpStatusCode.InternalServerError, "Failed to delete proof file.", null, null);
    }
}

// Config mode note: today anyone with a valid token can call Save on any submission - there is
// no approver concept at all. Expected setup is any_one mode with the actual HR/Payroll
// employee(s) who verify proofs listed explicitly as approvers - this is the first-ever
// authorization for this flow, not a replacement for an existing one.
private async Task TryCreateApprovalInstanceAsync(long submissionId, long requestorEmployeeId)
{
    try
    {
        var formDocId = await _approvalService.ResolveFormDocIdAsync(ApprovalModuleKeys.IncomeTax, IncomeTaxFormDocNames.ProofApproval);
        if (formDocId is null)
        {
            _logger.LogWarning("[{Layer}]: No 'Income Tax Proof Approval' FormDocMaster row found - skipping approval instance creation for submission {SubmissionId}", _LayerName, submissionId);
            return;
        }

        var result = await _approvalService.CreateInstance(new CreateApprovalInstanceModel
        {
            FormDocId = formDocId.Value,
            TransactionRecordId = submissionId,
            RequestorEmployeeId = requestorEmployeeId,
            CompanyMasterId = _meta.CompanyId,
            BranchMasterId = _meta.BranchId,
        });

        if (!result.IsSuccess || result.Data == null)
            _logger.LogWarning("[{Layer}]: Could not create approval instance for submission {SubmissionId}: {Message}", _LayerName, submissionId, result.Message);
    }
    catch (Exception ex)
    {
        _logger.LogError(ex, "[{Layer}]: Unexpected error creating approval instance for submission {SubmissionId}", _LayerName, submissionId);
    }
}

private async Task<bool> CanAccessAsync(long ownerEmployeeId)
{
    if (ownerEmployeeId == _meta.EmployeeMasterId) return true;
    return await _declarationRepo.IsHRAdminAsync(_meta.EmployeeMasterId);
}

