// Config mode note: today anyone with a valid token can call Save on any submission - there is
// no approver concept at all. Expected setup is any_one mode with the actual HR/Payroll
// employee(s) who verify proofs listed explicitly as approvers - this is the first-ever
// authorization for this flow, not a replacement for an existing one.
private async Task TryCreateApprovalInstanceAsync(long submissionId, long requestorEmployeeId)
{
    try
    {
        var formDocId = await _approvalService.ResolveFormDocIdAsync(ApprovalModuleKeys.IncomeTax, IncomeTaxFormDocNames.ProofApproval);
        if (formDocId is null)
        {
            _logger.LogWarning("[{Layer}]: No 'Income Tax Proof Approval' FormDocMaster row found - skipping approval instance creation for submission {SubmissionId}", _LayerName, submissionId);
            return;
        }

        var result = await _approvalService.CreateInstance(new CreateApprovalInstanceModel
        {
            FormDocId = formDocId.Value,
            TransactionRecordId = submissionId,
            RequestorEmployeeId = requestorEmployeeId,
            CompanyMasterId = _meta.CompanyId,
            BranchMasterId = _meta.BranchId,
        });

        if (!result.IsSuccess || result.Data == null)
            _logger.LogWarning("[{Layer}]: Could not create approval instance for submission {SubmissionId}: {Message}", _LayerName, submissionId, result.Message);
    }
    catch (Exception ex)
    {
        _logger.LogError(ex, "[{Layer}]: Unexpected error creating approval instance for submission {SubmissionId}", _LayerName, submissionId);
    }
}

