public async Task<ResponseModel> AcceptStatementAsync(long caseId, AcceptStatementModel model)
{
    var res = new ResponseModel();
    var companyId = _requestMetadata.CompanyId;
    try
    {
        var existing = await _repository.GetCaseByIdAsync(caseId, companyId);
        if (existing == null) return Fail(res, HttpStatusCode.NotFound, "F&F case not found.");

        // Accepting or disputing a statement is the departing employee's own act, and this
        // checked only that the case existed in the company - so any logged-in user could
        // post someone else's caseId and settle their statement for them. The employee comes
        // from the token; NotFound rather than Forbidden, so a caller cannot probe for which
        // case ids exist.
        if (existing.EmployeeMasterId != _requestMetadata.EmployeeMasterId)
        {
            _logger.LogWarning(
                "User {UserId} (employee {CallerId}) tried to accept F&F case {CaseId}, which belongs to employee {OwnerId}.",
                _requestMetadata.UserId, _requestMetadata.EmployeeMasterId, caseId, existing.EmployeeMasterId);
            return Fail(res, HttpStatusCode.NotFound, "F&F case not found.");
        }

        await _calculationService.RecordAcceptanceAsync(caseId, existing.EmployeeMasterId, companyId,
            model.AcceptanceResult, model.Remarks, _requestMetadata.UserId);
        return Success(res, "Acceptance recorded.");
    }
    catch (Exception e)
    {
        _logger.LogError(e, "Exception while recording acceptance for F&F case {Id}", caseId);
        return Fail(res, HttpStatusCode.InternalServerError, e.Message);
    }
}

