      try {
        const result = call();
        await (isObservable(result) ? firstValueFrom(result) : result);
        return false;
      } catch {
        e.component.cancelEditData();
        return true;
      }
    })();
  }

  onRowUpdating(e: any): void {
    if (!this.inlineEditing || !this.updateFn) return;
    const fn = this.updateFn;
    this.runSave(e, () => fn(e.key, e.newData, { ...e.oldData, ...e.newData }));
  }

  onRowInserting(e: any): void {
    if (!this.inlineEditing || !this.insertFn) return;
    const fn = this.insertFn;
    this.runSave(e, () => fn(e.data));
  }
  async onExporting(e: any): Promise<void> {
    const workbook = new ExcelJS.Workbook();
    const worksheet = workbook.addWorksheet('User Data');
    await exportDataGrid({
      component: e.component,
      worksheet,
      autoFilterEnabled: true,
    });
    const buffer = await workbook.xlsx.writeBuffer();
    saveAs(new Blob([buffer], { type: 'application/octet-stream' }), this.exportFileName);
    e.cancel = true;
  }
  onEditingStart(e: any): void {
    if (this.inlineEditing) {
      // Fires per cell in 'cell' mode; block locked cells, let the rest edit.
      const field = e.column?.dataField;
      if (this.isCellEditable && field && !this.isCellEditable(e.data, field)) e.cancel = true;
      return;
    }
    e.cancel = true;
    this.editRow.emit(e.data);
  }
  onRowRemoving(e: any): void {
    e.cancel = true;
    this.selectedRowForDelete = e.data;
    this.isDeletePopupVisible = true;
  }
  confirmDelete(): void {
    if (this.selectedRowForDelete) {
      if (this.inlineEditing && this.deleteFn) {
        const result = this.deleteFn(this.selectedRowForDelete);
        // Parent owns errors/toasts and the reload; swallow the rejection so it isn't unhandled.
        (isObservable(result) ? firstValueFrom(result) : result).catch(() => {});
      } else {
        this.deleteRow.emit(this.selectedRowForDelete);
      }
    }
    this.isDeletePopupVisible = false;
    this.selectedRowForDelete = null;
  }
  cancelDelete(): void {
    this.isDeletePopupVisible = false;
    this.selectedRowForDelete = null;
  }
}
<div class="app-grid-wrapper" [class.app-grid-wrapper--compact]="!fillViewport">
  <div class="app-grid-toolbar">
    <div class="app-grid-toolbar-left">
      @if (gridTitle) {
        <div class="app-grid-toolbar-heading">
          <h6 class="app-grid-title">
            @if (gridIcon) {
              <i [class]="gridIcon"></i>
            } @else {
              <i class="fa fa-table"></i>
            }
            <span>{{ gridTitle }}</span>
          </h6>
          @if (gridSubtitle) {
            <p class="app-grid-subtitle">{{ gridSubtitle }}</p>
          }
        </div>
      }
    </div>

    <div class="app-grid-toolbar-right">
      @if (showRefreshButton) {
        <dx-button
          text="Refresh"
          icon="refresh"
          stylingMode="outlined"
          [disabled]="refreshDisabled"
          (onClick)="refresh.emit()"
        ></dx-button>
      }
      @if (showAddButton) {
        <dx-button
          [text]="addButtonText"
          icon="add"
          stylingMode="contained"
          class="app-primary-btn"
          (onClick)="onAddClick()"
        ></dx-button>
      }
    </div>
  </div>

  <div
    class="app-grid-body app-grid-scroll-host"
    [class.app-grid-scroll-host--fill]="fillViewport"
    [class.app-grid-scroll-host--fit]="!fillViewport"
  >
    <dx-data-grid
      class="app-data-grid"
      [dataSource]="dataSource"
      [columns]="titleCasedColumns"
      [keyExpr]="keyExpr"
      [height]="fillViewport ? '100%' : 'auto'"
      [width]="'100%'"
      [loadPanel]="{ enabled: false }"
      (onCellPrepared)="onCellPrepared && onCellPrepared($event)"
      (onCellClick)="cellClick.emit($event)"
      (onEditorPreparing)="onEditorPreparing && onEditorPreparing($event)"
      (onEditingStart)="onEditingStart($event)"
      (onRowUpdating)="onRowUpdating($event)"
      (onRowInserting)="onRowInserting($event)"
      (onRowRemoving)="onRowRemoving($event)"
      [showBorders]="true"
      [showRowLines]="true"
      [columnAutoWidth]="columnAutoWidth"
      [wordWrapEnabled]="wordWrapEnabled"
      [rowAlternationEnabled]="true"
      [allowColumnReordering]="true"
      [allowColumnResizing]="true"
      columnResizingMode="widget"
      [columnHidingEnabled]="columnHidingEnabled && !inlineEditing"
      [remoteOperations]="false"
      [scrolling]="gridScrolling"
      [searchPanel]="{ visible: true, width: 240, placeholder: 'Search...' }"
      [groupPanel]="{ visible: showGroupPanel }"
      [filterRow]="{ visible: true }"
      [headerFilter]="{ visible: true }"
      [grouping]="{ autoExpandAll: false }"
      [editing]="editingConfig"
      [selection]="{ mode: 'multiple' }"
      [export]="{ enabled: true, allowExportSelectedData: true }"
      (onExporting)="onExporting($event)"
      [pager]="{
        showPageSizeSelector: true,
        allowedPageSizes: [5, 10, 20, 50],
        showInfo: true,
        showNavigationButtons: true,
      }"
      [paging]="{ pageSize: 10 }"
      [columnChooser]="{ enabled: true, mode: 'select' }"
      [stateStoring]="{
        enabled: enableStateStoring,
        type: 'localStorage',
        storageKey: storageKey,
      }"
    >
      @if (summaryItems.length) {
        <dxo-summary>
          @for (item of summaryItems; track item.column) {
            <dxi-total-item
              [column]="item.column"
              [summaryType]="item.summaryType"
              [valueFormat]="item.valueFormat"
            ></dxi-total-item>
          }
        </dxo-summary>
      }
    </dx-data-grid>
  </div>
</div>

<dx-popup
  title="Confirm Delete"
  [(visible)]="isDeletePopupVisible"
  [width]="350"
  [height]="200"
  [showCloseButton]="true"
>
  <div class="delete-popup-body">
    <p>Are you sure you want to delete this record?</p>

    <div class="popup-actions">
      <dx-button text="No" stylingMode="outlined" (onClick)="cancelDelete()"></dx-button>
      <dx-button
        text="Yes"
        type="danger"
        stylingMode="contained"
        (onClick)="confirmDelete()"
      ></dx-button>
    </div>
  </div>
</dx-popup>

