350	            this.toast.error(FnfApiService.messageOf(res, 'Calculation failed.'));
351	            return;
352	          }
353	          this.toast.success(FnfApiService.messageOf(res, 'Calculated.'));
354	          this.load();
355	        },
356	        error: (err) => this.toast.error(FnfApiService.errorMessage(err, 'Unable to calculate.')),
357	      });
358	  }
359	
360	  submit(): void {
361	    if (!confirm('Submit this settlement for approval? It cannot be edited afterwards.')) return;
362	    this.submitting = true;
363	    this.fnfApi
364	      .submit(this.caseId)
365	      .pipe(finalize(() => (this.submitting = false)))
366	      .subscribe({
367	        next: (res) => {
368	          if (!FnfApiService.isOk(res)) {
369	            this.toast.error(FnfApiService.messageOf(res, 'Submit failed.'));
370	            return;
371	          }
372	          this.toast.success(FnfApiService.messageOf(res, 'Submitted for approval.'));
373	          this.load();
374	        },
375	        error: (err) => this.toast.error(FnfApiService.errorMessage(err, 'Unable to submit.')),
376	      });
377	  }
378	
379	  // ---------------------------------------------------------------- Checks
380	
381	  openCheckEdit(kind: CheckKind, row: FnfCheckModel): void {
382	    this.checkPopupKind = kind;
383	    this.checkPopupRow = row;
384	    this.checkResult = row.result;
385	    this.checkRemarks = row.remarks ?? '';
386	    this.checkResultOptions = kind === 'Readiness' || kind === 'Handover' ? ['Yes', 'No'] : ['Pass', 'Fail', 'NA'];
387	    this.checkPopupVisible = true;
388	  }
389	
390	  saveCheck(): void {
391	    if (!this.checkPopupRow) return;
392	    this.checkBusy = true;
393	    this.fnfApi
394	      .updateCheck(this.caseId, { fnfCheckId: this.checkPopupRow.fnfCheckId, result: this.checkResult, remarks: this.checkRemarks })
395	      .pipe(finalize(() => (this.checkBusy = false)))
396	      .subscribe({
397	        next: (res) => {
398	          if (!FnfApiService.isOk(res)) {
399	            this.toast.error(FnfApiService.messageOf(res, 'Could not update.'));
400	            return;
401	          }
402	          this.checkPopupVisible = false;
403	          this.loadChecks(this.checkPopupKind);
404	          if (this.checkPopupKind === 'Readiness') this.load();
405	        },
406	        error: (err) => this.toast.error(FnfApiService.errorMessage(err, 'Could not update.')),
407	      });
408	  }
409	
410	  // -------------------------------------------------------------- Recovery
411	
412	  onAddRecovery(): void {
413	    this.isRecoveryEdit = false;
414	    this.editingRecoveryId = null;
415	    this.recoveryForm.reset({
416	      clearanceDepartment: 'IT',
417	      duesType: 'Advance',
418	      description: '',
419	      amount: 0,
420	      recoveryStatus: 'Confirmed',
421	      remarks: '',
422	    });
423	    this.recoveryPopupVisible = true;
424	  }
425	
426	  onEditRecovery(row: FnfRecoveryModel): void {
427	    this.isRecoveryEdit = true;
428	    this.editingRecoveryId = row.fnfRecoveryId;
429	    this.recoveryForm.reset({
430	      clearanceDepartment: row.clearanceDepartment,
431	      duesType: row.duesType,
432	      description: row.description ?? '',
433	      amount: row.amount,
434	      recoveryStatus: row.recoveryStatus,
435	      remarks: row.remarks ?? '',
436	    });
437	    this.recoveryPopupVisible = true;
438	  }
439	
440	  onDeleteRecovery(row: FnfRecoveryModel): void {
441	    this.fnfApi.deleteRecovery(this.caseId, row.fnfRecoveryId).subscribe({
442	      next: (res) => {
443	        if (!FnfApiService.isOk(res)) {
444	          this.toast.error(FnfApiService.messageOf(res, 'Delete failed.'));
445	          return;
446	        }
447	        this.toast.success('Recovery removed.');
448	        this.loadRecoveries();
449	      },
450	      error: (err) => this.toast.error(FnfApiService.errorMessage(err, 'Unable to delete recovery.')),
451	    });
452	  }
453	
454	  saveRecovery(): void {
455	    if (this.recoveryForm.invalid) {
456	      this.recoveryForm.markAllAsTouched();
457	      return;
458	    }
459	    this.recoveryBusy = true;
460	    const value: AddRecoveryModel = { fnfSettlementId: this.caseId, ...this.recoveryForm.value };
461	    const request$ = this.isRecoveryEdit
462	      ? this.fnfApi.updateRecovery(this.caseId, { fnfRecoveryId: this.editingRecoveryId!, ...value })
463	      : this.fnfApi.addRecovery(value);
464	
465	    request$.pipe(finalize(() => (this.recoveryBusy = false))).subscribe({
466	      next: (res) => {
467	        if (!FnfApiService.isOk(res)) {
468	          this.toast.error(FnfApiService.messageOf(res, 'Save failed.'));
469	          return;
470	        }
471	        this.toast.success(FnfApiService.messageOf(res, 'Saved.'));
472	        this.recoveryPopupVisible = false;
473	        this.loadRecoveries();
474	      },
475	      error: (err) => this.toast.error(FnfApiService.errorMessage(err, 'Unable to save recovery.')),
476	    });
477	  }
478	
479	  get recoveryTotal(): number {
480	    return this.recoveries
481	      .filter((r) => r.recoveryStatus === 'Confirmed' || r.recoveryStatus === 'Waived')
482	      .reduce((sum, r) => sum + (r.amount || 0), 0);
483	  }
484	
485	  // -------------------------------------------------------- Settlement detail
486	
487	  onAddDetail(): void {
488	    this.isDetailEdit = false;
489	    this.editingDetailId = null;
490	    this.detailForm.reset({ componentType: 'OtherRecovery', salaryHeadMasterId: null, addDeduct: 'Deduct', amount: 0, remarks: '' });
491	    this.detailPopupVisible = true;
492	  }
493	
494	  onEditDetail(row: FnfSettlementDetailModel): void {
495	    if (row.isAuto) {
496	      this.toast.error('This line is calculated automatically — edit the configuration or recalculate instead.');
497	      return;
498	    }
499	    this.isDetailEdit = true;
500	    this.editingDetailId = row.fnfSettlementDetailId;
501	    this.detailForm.reset({
502	      componentType: row.componentType,
503	      salaryHeadMasterId: row.salaryHeadMasterId,
504	      addDeduct: row.addDeduct,
505	      amount: row.amount,
506	      remarks: row.remarks ?? '',
507	    });
508	    this.detailPopupVisible = true;
509	  }
510	
511	  onDeleteDetail(row: FnfSettlementDetailModel): void {
512	    if (row.isAuto) {
513	      this.toast.error('This line is calculated automatically — it would come back on the next Calculate. Remove its cause instead (for example waive the recovery).');
514	      return;
515	    }
516	    this.fnfApi.deleteManualDetail(this.caseId, row.fnfSettlementDetailId).subscribe({
517	      next: (res) => {
518	        if (!FnfApiService.isOk(res)) {
519	          this.toast.error(FnfApiService.messageOf(res, 'Delete failed.'));
520	          return;
521	        }
522	        this.toast.success('Line removed.');
523	        this.loadSettlementDetails();
524	      },
525	      error: (err) => this.toast.error(FnfApiService.errorMessage(err, 'Unable to delete line.')),
526	    });
527	  }
528	
529	  saveDetail(): void {
530	    if (this.detailForm.invalid) {
531	      this.detailForm.markAllAsTouched();
532	      return;
533	    }
534	    this.detailBusy = true;
535	    const value = this.detailForm.value;
536	    const request$ = this.isDetailEdit
537	      ? this.fnfApi.updateManualDetail(this.caseId, { fnfSettlementDetailId: this.editingDetailId!, ...value })
538	      : this.fnfApi.addManualDetail({ fnfSettlementId: this.caseId, ...value });
539	
540	    request$.pipe(finalize(() => (this.detailBusy = false))).subscribe({
541	      next: (res) => {
542	        if (!FnfApiService.isOk(res)) {
543	          this.toast.error(FnfApiService.messageOf(res, 'Save failed.'));
544	          return;
545	        }
546	        this.toast.success(FnfApiService.messageOf(res, 'Saved.'));
547	        this.detailPopupVisible = false;
548	        this.loadSettlementDetails();
549	        this.load();
550	      },
551	      error: (err) => this.toast.error(FnfApiService.errorMessage(err, 'Unable to save line.')),
552	    });
553	  }
