      <div class="col-md-6">
        <label class="form-label">Department</label>
        <dx-select-box formControlName="clearanceDepartment" [dataSource]="clearanceDepartments"></dx-select-box>
      </div>
      <div class="col-md-6">
        <label class="form-label">Dues Type</label>
        <dx-select-box formControlName="duesType" [dataSource]="duesTypes"></dx-select-box>
      </div>
    </div>
    <div class="mb-2">
      <label class="form-label">Description</label>
      <dx-text-box formControlName="description"></dx-text-box>
    </div>
    <div class="row g-2 mb-2">
      <div class="col-md-6">
        <label class="form-label">Amount</label>
        <dx-number-box formControlName="amount" [min]="0" format="#,##0.##"></dx-number-box>
      </div>
      <div class="col-md-6">
        <label class="form-label">Status</label>
        <dx-select-box formControlName="recoveryStatus" [dataSource]="recoveryStatuses"></dx-select-box>
      </div>
    </div>
    <div class="mb-2">
      <label class="form-label">Remarks</label>
      <dx-text-area formControlName="remarks" [height]="60"></dx-text-area>
    </div>

    <div class="popup-actions">
      <dx-button text="Cancel" stylingMode="outlined" [disabled]="recoveryBusy" (onClick)="recoveryPopupVisible = false"></dx-button>
      <dx-button text="Save" type="default" stylingMode="contained" [disabled]="recoveryBusy" (onClick)="saveRecovery()"></dx-button>
    </div>
  </form>
</dx-popup>

<!-- ============================ Manual detail popup ============================ -->
<dx-popup
  [(visible)]="detailPopupVisible"
  [showTitle]="true"
  [title]="isDetailEdit ? 'Edit Line' : 'Add Manual Line'"
