      <label class="form-label">Salary Head</label>
      <dx-select-box formControlName="salaryHeadMasterId" [dataSource]="salaryHeads" valueExpr="id" displayExpr="name" [showClearButton]="true" placeholder="not set"></dx-select-box>
    </div>
    <div class="row g-2 mb-2">
      <div class="col-md-6">
        <label class="form-label">Add / Deduct</label>
        <dx-select-box formControlName="addDeduct" [dataSource]="addDeductOptions"></dx-select-box>
      </div>
      <div class="col-md-6">
        <label class="form-label">Amount</label>
        <dx-number-box formControlName="amount" [min]="0" format="#,##0.##"></dx-number-box>
      </div>
    </div>
    <div class="mb-2">
      <label class="form-label">Remarks</label>
      <dx-text-area formControlName="remarks" [height]="60"></dx-text-area>
    </div>

    <div class="popup-actions">
      <dx-button text="Cancel" stylingMode="outlined" [disabled]="detailBusy" (onClick)="detailPopupVisible = false"></dx-button>
      <dx-button text="Save" type="default" stylingMode="contained" [disabled]="detailBusy" (onClick)="saveDetail()"></dx-button>
    </div>
  </form>
</dx-popup>

