  /** Readiness/Handover answer Yes/No; Verification answers Pass/Fail/NA. Only Result and Remarks are editable. */
  private buildCheckColumns(resultOptions: string[]): Record<string, unknown>[] {
    return [
      { dataField: 'checkName', caption: 'Requirement', allowEditing: false },
      {
        dataField: 'isRequired',
