  /** Days/Rate/Source are calculation output; Auto lines are locked row-wide by `isDetailCellEditable`. */
  private buildSettlementColumns(): Record<string, unknown>[] {
    return [
      { dataField: 'componentType', caption: 'Component', ...EDITABLE, lookup: { dataSource: COMPONENT_TYPES }, validationRules: [REQUIRED] },
      {
        dataField: 'salaryHeadMasterId',
        caption: 'Salary Head',
        ...EDITABLE,
        lookup: { dataSource: this.salaryHeads, valueExpr: 'id', displayExpr: 'name', allowClearing: true },
      },
      { dataField: 'addDeduct', caption: 'Add/Deduct', width: 110, ...EDITABLE, lookup: { dataSource: ADD_DEDUCT }, validationRules: [REQUIRED] },
      { dataField: 'days', caption: 'Days', dataType: 'number', width: 80, allowEditing: false },
      { dataField: 'rate', caption: 'Rate', dataType: 'number', format: { type: 'fixedPoint', precision: 2 }, width: 100, allowEditing: false },
