# replace everything from Checks section to end
a=s.index("  // ---------------------------------------------------------------- Checks")
s=s[:a]+'''  // ------------------------------------------------------- Inline grid saves
  //
  // Each grid saves one cell at a time. A rejected promise puts the cell back to its old value; the
  // toast is shown here. Every save reloads its list so server-computed fields stay current.

  private persist(request$: Observable<unknown>, failMessage: string, after: () => void): Promise<void> {
    return new Promise((resolve, reject) => {
      request$.subscribe({
        next: (res) => {
          if (!FnfApiService.isOk(res)) {
            this.toast.error(FnfApiService.messageOf(res, failMessage));
            reject(res);
            return;
          }
          after();
          resolve();
        },
        error: (err) => {
          this.toast.error(FnfApiService.errorMessage(err, failMessage));
          reject(err);
        },
      });
    });
  }

  private saveCheck(kind: CheckKind, row: FnfCheckModel): Promise<void> {
    return this.persist(
      this.fnfApi.updateCheck(this.caseId, { fnfCheckId: row.fnfCheckId, result: row.result || null, remarks: row.remarks || null }),
      'Could not update.',
      () => {
        this.loadChecks(kind);
        // Readiness answers drive the clearance banner, so refresh the case too.
        if (kind === 'Readiness') this.load();
      },
    );
  }

  saveReadiness = (_key: number, _changes: Partial<FnfCheckModel>, row: FnfCheckModel) => this.saveCheck('Readiness', row);
  saveVerification = (_key: number, _changes: Partial<FnfCheckModel>, row: FnfCheckModel) => this.saveCheck('Verification', row);
  saveHandover = (_key: number, _changes: Partial<FnfCheckModel>, row: FnfCheckModel) => this.saveCheck('Handover', row);

  // -------------------------------------------------------------- Recovery

  private toRecoveryPayload(row: FnfRecoveryModel) {
    return {
      fnfSettlementId: this.caseId,
      clearanceDepartment: row.clearanceDepartment,
      duesType: row.duesType,
      description: row.description || null,
      amount: Number(row.amount ?? 0),
      recoveryStatus: row.recoveryStatus,
      remarks: row.remarks || null,
    };
  }

  addRecovery = (row: FnfRecoveryModel) =>
    this.persist(this.fnfApi.addRecovery(this.toRecoveryPayload(row)), 'Unable to save recovery.', () => this.loadRecoveries());

  updateRecovery = (key: number, _changes: Partial<FnfRecoveryModel>, row: FnfRecoveryModel) =>
    this.persist(
      this.fnfApi.updateRecovery(this.caseId, { fnfRecoveryId: key, ...this.toRecoveryPayload(row) }),
      'Unable to save recovery.',
      () => this.loadRecoveries(),
    );

  deleteRecovery = (row: FnfRecoveryModel) =>
    this.persist(this.fnfApi.deleteRecovery(this.caseId, row.fnfRecoveryId), 'Unable to delete recovery.', () => {
      this.toast.success('Recovery removed.');
      this.loadRecoveries();
    });

  get recoveryTotal(): number {
    return this.recoveries
      .filter((r) => r.recoveryStatus === 'Confirmed' || r.recoveryStatus === 'Waived')
      .reduce((sum, r) => sum + (r.amount || 0), 0);
  }

  // -------------------------------------------------------- Settlement detail

  /** An automatically-calculated line is recomputed on every Calculate, so none of its cells are editable. */
  isDetailCellEditable = (row: FnfSettlementDetailModel) => !row?.isAuto;

  private toDetailPayload(row: FnfSettlementDetailModel) {
    return {
      componentType: row.componentType,
      salaryHeadMasterId: row.salaryHeadMasterId ?? null,
      addDeduct: row.addDeduct,
      amount: Number(row.amount ?? 0),
      remarks: row.remarks || null,
    };
  }

  /** Lines change the totals in the banner, so the case reloads too. */
  private afterDetailSaved(): void {
    this.loadSettlementDetails();
    this.load();
  }

  addDetail = (row: FnfSettlementDetailModel) =>
    this.persist(
      this.fnfApi.addManualDetail({ fnfSettlementId: this.caseId, ...this.toDetailPayload(row) }),
      'Unable to save line.',
      () => this.afterDetailSaved(),
    );

  updateDetail = (key: number, _changes: Partial<FnfSettlementDetailModel>, row: FnfSettlementDetailModel) =>
    this.persist(
      this.fnfApi.updateManualDetail(this.caseId, { fnfSettlementDetailId: key, ...this.toDetailPayload(row) }),
      'Unable to save line.',
      () => this.afterDetailSaved(),
    );

  deleteDetail = (row: FnfSettlementDetailModel): Promise<void> => {
    if (row.isAuto) {
      this.toast.error('This line is calculated automatically — it would come back on the next Calculate. Remove its cause instead (for example waive the recovery).');
      return Promise.reject();
    }
    return this.persist(this.fnfApi.deleteManualDetail(this.caseId, row.fnfSettlementDetailId), 'Unable to delete line.', () => {
      this.toast.success('Line removed.');
      this.afterDetailSaved();
    });
  };
}
'''
# constants
s=s.replace("""const ADD_DEDUCT: AddDeduct[] = ['Add', 'Deduct'];
