    public async Task<ResponseModel> GetClearanceDepartmentsAsync()
    {
        var res = new ResponseModel();
        var companyId = _requestMetadata.CompanyId;
        var role = _requestMetadata.UserRole;
        try
        {
            if (!IsAdminRole(role))
                return Fail(res, HttpStatusCode.Forbidden, "F&F Configuration is limited to Admin and HR Admin.");

            var (useCustom, options) = await _repository.GetClearanceDepartmentPickerAsync(companyId);
            var model = new FnfClearanceDepartmentConfigModel
            {
                UseCustomClearanceDepartments = useCustom,
                Departments = options,
            };
            return Success(res, "Fetched exit-clearance department options.", model);
        }
        catch (Exception e)
        {
            _logger.LogError(e, "Exception while fetching F&F clearance department options");
            return Fail(res, HttpStatusCode.InternalServerError, e.Message);
        }
    }

    public async Task<ResponseModel> UpdateClearanceDepartmentsAsync(UpdateFnfClearanceDepartmentsModel model)
    public async Task<(bool UseCustom, List<FnfClearanceDepartmentOptionModel> Options)> GetClearanceDepartmentPickerAsync(long companyMasterId)
    {
        var useCustom = await _repo.ExecuteScalarAsync<bool>(
            "SELECT ISNULL(UseCustomClearanceDepartments, 0) FROM HR_FNFConfig WHERE CompanyMasterID = @CompanyMasterId AND Status = 1",
            new { CompanyMasterId = companyMasterId });

        const string sql = @"
            SELECT D.DepartmentMasterID AS DepartmentMasterId, D.DepartmentCode, D.DepartmentName,
                   CASE WHEN C.FNFClearanceDepartmentID IS NULL THEN 0 ELSE 1 END AS IsSelected,
                   C.ChecklistHint, ISNULL(C.SortOrder, 0) AS SortOrder
            FROM   HR_DepartmentMaster D
            LEFT   JOIN HR_FNFClearanceDepartment C
                   ON  C.DepartmentMasterID = D.DepartmentMasterID AND C.CompanyMasterID = @CompanyMasterId
            WHERE  D.CompanyMasterID = @CompanyMasterId AND D.Status = 1
            ORDER  BY ISNULL(C.SortOrder, 999), D.DepartmentName";

        var options = (await _repo.QueryAsync<FnfClearanceDepartmentOptionModel>(sql, new { CompanyMasterId = companyMasterId })).ToList();
        return (useCustom, options);
    }

