    public async Task<ResponseModel> GetClearanceDepartmentsAsync()
    {
        var res = new ResponseModel();
        var companyId = _requestMetadata.CompanyId;
        var role = _requestMetadata.UserRole;
        try
        {
            if (!IsAdminRole(role))
                return Fail(res, HttpStatusCode.Forbidden, "F&F Configuration is limited to Admin and HR Admin.");

            var (useCustom, options) = await _repository.GetClearanceDepartmentPickerAsync(companyId);
            var model = new FnfClearanceDepartmentConfigModel
            {
                UseCustomClearanceDepartments = useCustom,
                Departments = options,
            };
            return Success(res, "Fetched exit-clearance department options.", model);
        }
        catch (Exception e)
        {
            _logger.LogError(e, "Exception while fetching F&F clearance department options");
            return Fail(res, HttpStatusCode.InternalServerError, e.Message);
        }
    }

