    /// clearance is appended unconditionally - it is not a department.
    /// </summary>
    private async Task<List<(string Code, string Name, string Hint, int SortOrder)>> GetClearanceChecklistAsync(long exitId)
    {
        const string configSql = @"
            SELECT ISNULL(F.UseCustomClearanceDepartments, 0) AS UseCustom, X.CompanyMasterID AS CompanyMasterId
            FROM   HR_ExitFormality X
            LEFT   JOIN HR_FNFConfig F ON F.CompanyMasterID = X.CompanyMasterID AND F.Status = 1
            WHERE  X.ExitFormalityID = @ExitId";

        var config = await _repo.QueryFirstOrDefaultAsync<(bool UseCustom, long CompanyMasterId)>(configSql, new { ExitId = exitId });

        List<(string Code, string Name, string Hint, int SortOrder)> departments;

        if (config.UseCustom)
        {
            const string configuredSql = @"
                SELECT D.DepartmentCode AS Code, D.DepartmentName AS Name,
                       ISNULL(C.ChecklistHint, '') AS Hint, C.SortOrder
                FROM   HR_FNFClearanceDepartment C
                INNER  JOIN HR_DepartmentMaster D ON D.DepartmentMasterID = C.DepartmentMasterID
                WHERE  C.CompanyMasterID = @CompanyMasterId
                ORDER  BY C.SortOrder, C.FNFClearanceDepartmentID";

            departments = (await _repo.QueryAsync<(string, string, string, int)>(configuredSql,
                new { config.CompanyMasterId })).ToList();
        }
        else
        {
            departments = FallbackDepartments.ToList();
        }

        departments.Add(ManagerClearance);
        return departments;
    }

