    /// The department checkpoints for one exit, resolved from this exit's own company - see
    /// GetClearanceChecklistForCompanyAsync.
    /// </summary>
    private async Task<List<(string Code, string Name, string Hint, int SortOrder)>> GetClearanceChecklistAsync(long exitId)
    {
        var companyId = await _repo.ExecuteScalarAsync<long?>(
            "SELECT CompanyMasterID FROM HR_ExitFormality WHERE ExitFormalityID = @ExitId", new { ExitId = exitId });
        return await GetClearanceChecklistForCompanyAsync(companyId ?? 0);
    }

    public async Task<List<ClearanceDepartmentOptionModel>> GetClearanceDepartmentsAsync(long companyId) =>
        (await GetClearanceChecklistForCompanyAsync(companyId))
            .Select(d => new ClearanceDepartmentOptionModel { Code = d.Code, Name = d.Name })
            .ToList();

    /// <summary>
    /// One company's clearance departments: its admin-configured HR_FNFClearanceDepartment
    /// selection if it has ever saved one (even an empty one - see
    /// FnfConfigRepository.ReplaceClearanceDepartmentsAsync), else the fixed legacy checklist every
    /// company used before that config screen existed. Reporting Manager clearance is appended
    /// unconditionally - it is not a department. The exit checklist and the F&amp;F recovery
    /// department picker both read this, so a recovery's department is always one the exit knows.
    /// </summary>
    private async Task<List<(string Code, string Name, string Hint, int SortOrder)>> GetClearanceChecklistForCompanyAsync(long companyId)
    {
        var useCustom = await _repo.ExecuteScalarAsync<bool?>(
            "SELECT TOP 1 UseCustomClearanceDepartments FROM HR_FNFConfig WHERE CompanyMasterID = @CompanyMasterId AND Status = 1",
            new { CompanyMasterId = companyId }) ?? false;

        List<(string Code, string Name, string Hint, int SortOrder)> departments;

        if (useCustom)
        {
            const string configuredSql = @"
                SELECT D.DepartmentCode AS Code, D.DepartmentName AS Name,
                       ISNULL(C.ChecklistHint, '') AS Hint, C.SortOrder
                FROM   HR_FNFClearanceDepartment C
                INNER  JOIN HR_DepartmentMaster D ON D.DepartmentMasterID = C.DepartmentMasterID
                WHERE  C.CompanyMasterID = @CompanyMasterId
                ORDER  BY C.SortOrder, C.FNFClearanceDepartmentID";

            departments = (await _repo.QueryAsync<(string, string, string, int)>(configuredSql,
                new { CompanyMasterId = companyId })).ToList();
        }
        else
        {
            departments = FallbackDepartments.ToList();
        }

        departments.Add(ManagerClearance);
        return departments;
    }

