  ngOnInit(): void {
    this.leaveColumns = [
      { dataField: 'code', caption: 'Code', width: 90 },
      { dataField: 'name', caption: 'Leave Type' },
      {
        dataField: 'isPaidLeave',
        caption: 'Paid',
        width: 90,
        cellTemplate: (container: HTMLElement, options: any) => {
          container.innerText = options.data?.isPaidLeave ? 'Yes' : 'No';
        },
      },
      {
        dataField: 'carryForward',
        caption: 'Carry Fwd',
        width: 100,
        cellTemplate: (container: HTMLElement, options: any) => {
          container.innerText = options.data?.carryForward ? 'Yes' : 'No';
        },
      },
      {
        dataField: 'isEncashable',
        caption: 'Encashable',
        width: 110,
        cellTemplate: (container: HTMLElement, options: any) => {
          const btn = document.createElement('button');
          btn.className = `status-pill ${options.data?.isEncashable ? 'status-approved' : 'status-hold'}`;
          btn.style.cursor = 'pointer';
          btn.style.border = 'none';
          btn.innerText = options.data?.isEncashable ? 'Yes' : 'No';
          btn.onclick = () => this.toggleEncashable(options.data);
          container.appendChild(btn);
        },
      },
    ];

    this.load();
    this.loadLeaveTypes();
  }

  toggleEncashable(row: ListEncashableLeaveModel): void {
    const next = !row.isEncashable;
    this.fnfApi.updateEncashableFlag(row.leaveMasterId, next).subscribe({
      next: (res) => {
        if (!FnfApiService.isOk(res)) {
          this.toast.error(FnfApiService.messageOf(res, 'Could not update.'));
          return;
        }
        row.isEncashable = next;
        this.leaveRows = [...this.leaveRows];
        this.encashableLeaveCount = this.leaveRows.filter((r) => r.isEncashable).length;
      },
      error: (err) => this.toast.error(FnfApiService.errorMessage(err, 'Could not update.')),
    });
  }

