-- Pre-flight: stop cleanly (nothing runs) if a table we reference is missing.
DECLARE @missing NVARCHAR(MAX) = N'';
SELECT @missing = @missing + N' ' + t.n
FROM (VALUES (N'HR_EmployeeMaster'), (N'HR_CMS_MealSession'), (N'HR_MenuItems'), (N'HR_MenuActions'),
             (N'HR_RolesMaster'), (N'HR_RolePermissions'), (N'HR_UserMaster')) AS t(n)
WHERE OBJECT_ID(N'dbo.' + t.n, N'U') IS NULL;
IF @missing <> N''
BEGIN
    PRINT 'ABORTED - missing base tables:' + @missing;
    SET NOEXEC ON;
END
GO

GO

/* ════════════════════════════════════════════════════════════════════════════════════════
   PART 3 - Grant VIEW / CREATE / DELETE on Meal Booking
   ════════════════════════════════════════════════════════════════════════════════════════ */

-- ▼▼ EDIT HERE ▼▼
-- Roles (HR_RolesMaster.RoleCode) that may book meals. Add the role your employees log in with.
-- (A super-admin role already has every right and needs no row here.)
DECLARE @RoleCodes TABLE (RoleCode VARCHAR(50));
INSERT INTO @RoleCodes VALUES ('ADMIN');

-- 1 = also give the rights directly to every active login whose employee has Canteen Facility ticked.
DECLARE @GrantToCanteenEmployees BIT = 1;
-- ▲▲ EDIT HERE ▲▲

DECLARE @MenuId BIGINT = (SELECT TOP 1 [MenuID] FROM [dbo].[HR_MenuItems]
                          WHERE [NavigateUrl] = '/canteen-management/meal-booking' ORDER BY [IsActive] DESC, [MenuID] DESC);

DECLARE @Actions TABLE (ActionId INT);
INSERT INTO @Actions
SELECT [ActionId] FROM [dbo].[HR_MenuActions] WHERE [ActionCode] IN ('VIEW', 'CREATE', 'DELETE');


    -- Canteen employees whose login still can NOT book (no role grant and no direct grant).
    -- Should return 0 rows. Super-admin roles are not counted here and are fine.
    SELECT e.EmployeeMasterID, e.FirstName, um.UserMasterID, um.UserName
    FROM HR_EmployeeMaster e
    JOIN HR_UserMaster um ON um.EmployeeMasterID = e.EmployeeMasterID AND um.Status = 1
    WHERE e.IsCanteenFacility = 1
      AND NOT EXISTS (SELECT 1 FROM HR_UserScreenAccess sa
                      JOIN HR_MenuItems m ON m.MenuID = sa.MenuId
                      WHERE sa.UserId = um.UserMasterID AND m.NavigateUrl = '/canteen-management/meal-booking')
      AND NOT EXISTS (SELECT 1 FROM HR_UserRoles ur
                      JOIN HR_RolePermissions rp ON rp.RoleId = ur.RoleId
                      JOIN HR_MenuItems m ON m.MenuID = rp.MenuId
                      WHERE ur.UserId = um.UserMasterID AND m.NavigateUrl = '/canteen-management/meal-booking');
*/

